1	// Production web requires force-dynamic for runtime database access
2	// Capacitor builds: API routes are moved aside by scripts/build-capacitor.sh
3	export const dynamic = 'force-dynamic';
4	
5	/**
6	 * Living Work expressions — the member declares that an expression belongs to
7	 * a work (Work Home, Slice 6). This file is the FIRST writer of
8	 * `living_work_expressions`; until it existed the table had no writer at all.
9	 *
10	 * POST   — "this belongs to that work." A member act, never a side effect.
11	 * DELETE — the member takes the declaration back. The expression itself is
12	 *          untouched: removing "this belongs to that" removes a statement,
13	 *          not the thing stated about.
14	 *
15	 * WHAT THIS ROUTE REFUSES:
16	 *
17	 *   - **No system placement.** There is no classification, no "seems related",
18	 *     no bulk adopt. One expression per declaration, named by the member.
19	 *   - **Only expression types the Studio can actually hold.** `expression_type`
20	 *     is open in the schema by ratified design, but this route accepts only
21	 *     'manuscript' — the one instrument that exists. Accepting a type the
22	 *     Studio cannot show would store a claim no surface can honor.
23	 *   - **Ownership on both ends.** The declaring member must own the work
24	 *     (refuseDeclaration, Guard 1) AND the manuscript. A foreign id on either
25	 *     side is a 404, not a hint that the row exists.
26	 */
27	
28	import { NextRequest, NextResponse } from 'next/server';
29	import { query } from '@/lib/db/postgres';
30	import { getMemberIdFromRequest } from '@/lib/auth/getMemberFromRequest';
31	import { refuseDeclaration } from '@/lib/livingWork/domain';
32	
33	/** The one expression type the Studio can currently hold. */
34	const DECLARABLE_TYPES = ['manuscript'] as const;
35	
36	interface ExpressionRow {
37	  id: string;
38	  expression_type: string;
39	  expression_id: string;
40	  declared_at: string;
41	}
42	
43	export async function POST(request: NextRequest, ctx: { params: Promise<{ id: string }> }) {
44	  if (process.env.CAPACITOR_BUILD) {
45	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
46	  }
47	  const { id: livingWorkId } = await ctx.params;
48	  try {
49	    const memberId = await getMemberIdFromRequest(request);
50	    if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
51	
52	    const body = (await request.json().catch(() => ({}))) as {
53	      expressionType?: unknown;
54	      expressionId?: unknown;
55	    };
56	    const expressionType = typeof body.expressionType === 'string' ? body.expressionType : '';
57	    const expressionId = typeof body.expressionId === 'string' ? body.expressionId : '';
58	
59	    if (!(DECLARABLE_TYPES as readonly string[]).includes(expressionType)) {
60	      return NextResponse.json(
61	        { error: 'Only a manuscript can be placed in a work for now' },
62	        { status: 400 }
63	      );
64	    }
65	
66	    // Fetch by id alone and let the domain guard decide ownership, so the
67	    // ratified refusal order is the one actually exercised. Both "no such
68	    // work" and "someone else's work" leave as 404: a foreign id learns
69	    // nothing.
70	    const workRes = await query<{ id: string; member_id: string }>(
71	      `SELECT id, member_id FROM living_works WHERE id = $1`,
72	      [livingWorkId]
73	    );
74	    const work = workRes.rows[0]
75	      ? { id: workRes.rows[0].id, memberId: workRes.rows[0].member_id }
76	      : null;
77	
78	    const refusal = refuseDeclaration(
79	      { livingWorkId, expressionType, expressionId, declaredBy: memberId },
80	      work
81	    );
82	    if (refusal === 'missing_living_work' || refusal === 'not_the_owner') {
83	      return NextResponse.json({ error: 'Not found' }, { status: 404 });
84	    }
85	    if (refusal !== null) {
86	      return NextResponse.json({ error: refusal }, { status: 400 });
87	    }
88	
89	    const manuscript = await query<{ id: string }>(
90	      `SELECT id FROM member_manuscripts WHERE id = $1 AND member_id = $2`,
91	      [expressionId, memberId]
92	    );
93	    if (manuscript.rows.length === 0) {
94	      return NextResponse.json({ error: 'Not found' }, { status: 404 });
95	    }
96	
97	    // Declaring twice is not an error — the member is saying something already
98	    // true. The unique constraint absorbs it; the response says which happened.
99	    const inserted = await query<ExpressionRow>(
100	      `INSERT INTO living_work_expressions
101	         (living_work_id, expression_type, expression_id, declared_by)
102	       VALUES ($1, $2, $3, $4)
103	       ON CONFLICT (living_work_id, expression_type, expression_id) DO NOTHING
104	       RETURNING id, expression_type, expression_id, declared_at`,
105	      [livingWorkId, expressionType, expressionId, memberId]
106	    );
107	    if (inserted.rows.length === 0) {
108	      return NextResponse.json({ alreadyDeclared: true }, { status: 200 });
109	    }
110	    const r = inserted.rows[0];
111	    return NextResponse.json(
112	      {
113	        expression: {
114	          id: r.id,
115	          expressionType: r.expression_type,
116	          expressionId: r.expression_id,
117	          declaredAt: r.declared_at,
118	        },
119	      },
120	      { status: 201 }
121	    );
122	  } catch (error) {
123	    console.error('[living-works] declare expression failed', error);
124	    return NextResponse.json({ error: 'Could not place that in your work' }, { status: 500 });
125	  }
126	}
127	
128	export async function DELETE(request: NextRequest, ctx: { params: Promise<{ id: string }> }) {
129	  if (process.env.CAPACITOR_BUILD) {
130	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
131	  }
132	  const { id: livingWorkId } = await ctx.params;
133	  try {
134	    const memberId = await getMemberIdFromRequest(request);
135	    if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
136	
137	    const url = new URL(request.url);
138	    const expressionType = url.searchParams.get('expressionType') ?? '';
139	    const expressionId = url.searchParams.get('expressionId') ?? '';
140	    if (!expressionType || !expressionId) {
141	      return NextResponse.json({ error: 'expressionType and expressionId required' }, { status: 400 });
142	    }
143	
144	    // Member-scoped through the owning work, in the predicate: a declaration
145	    // on someone else's work cannot be reached, let alone removed.
146	    const removed = await query<{ id: string }>(
147	      `DELETE FROM living_work_expressions e
148	        USING living_works w
149	        WHERE e.living_work_id = w.id
150	          AND w.id = $1 AND w.member_id = $2
151	          AND e.expression_type = $3 AND e.expression_id = $4
152	       RETURNING e.id`,
153	      [livingWorkId, memberId, expressionType, expressionId]
154	    );
155	    if (removed.rows.length === 0) {
156	      return NextResponse.json({ error: 'Not found' }, { status: 404 });
157	    }
158	    return NextResponse.json({ withdrawn: removed.rows[0].id });
159	  } catch (error) {
160	    console.error('[living-works] withdraw expression failed', error);
161	    return NextResponse.json({ error: 'Could not remove that from your work' }, { status: 500 });
162	  }
163	}
