36	import { memberRef } from '@/lib/privacy/memberRef';
37	import { claimArrival, recordSuppliedArrival } from '@/lib/manuscript/source/arrivals';
38	import { detectOmission, omissionMarker } from '@/lib/manuscript/source/omission';
39	
40	const MAX_TEXT_CHARS = 2_000_000; // ~a very long book; hard cap for sanity
41	
42	export async function GET(request: NextRequest) {
43	  if (process.env.CAPACITOR_BUILD) {
44	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
45	  }
46	  try {
47	    const memberId = await getMemberIdFromRequest(request);
48	    if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
49	
50	    const result = await query<{
51	      id: string;
52	      title: string | null;
53	      created_at: string;
54	      section_count: string;
55	      char_count: string;
56	      keep_count: string;
57	      last_written_at: string | null;
58	      draft_char_count: string | null;
59	      has_draft_writing: boolean;
60	      has_writing: boolean;
61	      has_current_member_contribution: boolean;
62	    }>(
63	      `SELECT m.id, m.title, m.created_at,
64	              (SELECT count(*) FROM manuscript_sections s WHERE s.manuscript_id = m.id) AS section_count,
65	              (SELECT coalesce(sum(length(s.body)), 0) FROM manuscript_sections s WHERE s.manuscript_id = m.id) AS char_count,
66	              (SELECT count(*) FROM manuscript_keeps k WHERE k.manuscript_id = m.id) AS keep_count,
67	              -- ⛔ DRAFT ACTIVITY — a member act, but NOT NECESSARILY WRITING.
68	              --
69	              -- ⚠️ CORRECTED 2026-09-08 (STUDIO-WRITING-PRESENCE-01). The
70	              -- previous version of this comment enumerated the writers to
71	              -- updated_at and concluded that the column advances only when
72	              -- the member actually writes. That enumeration was INCOMPLETE and
73	              -- the conclusion was FALSE:
74	              --
75	              --   draft/checkpoint/route.ts:145  UPDATE manuscript_working_drafts
76	              --      SET version, revision_count, updated_at, last_idempotency_*
77	              --      ⛔ and NO content.
78	              --
79	              -- So a member may import a book, let the draft be seeded verbatim,
80	              -- press "Keep a version", and advance BOTH updated_at and the
81	              -- revision trail without authoring a single character. The two
82	              -- signals are not independent evidence of authorship; they report
83	              -- the same weaker fact — that a post-creation draft act occurred.
84	              --
85	              -- What this column therefore establishes is MEMBER DRAFT ACTIVITY:
86	              -- saving, checkpointing, restoring, or editing. It does not
87	              -- establish writing, and nothing may render it as a writing time.
88	              -- Authorship is established below, by
89	              -- has_current_member_contribution, against the durable
90	              -- revision-1 baseline.
91	              --
92	              -- Kept as last_written_at on the wire only to avoid unrelated
93	              -- compatibility work. ⛔ It may not be used as authority for
94	              -- continuability and may not render as "written <when>".
95	              (SELECT CASE WHEN d.updated_at > d.created_at THEN d.updated_at END
96	                 FROM manuscript_working_drafts d
97	                WHERE d.manuscript_id = m.id) AS last_written_at,
98	
99	              -- STUDIO-WRITING-PRESENCE-01 · three truths, none standing in for
100	              -- another. char_count above is SOURCE extent and stays that.
101	              (SELECT length(d.content) FROM manuscript_working_drafts d
102	                WHERE d.manuscript_id = m.id) AS draft_char_count,
103	
104	              -- Substantive draft presence. Whitespace is not writing; this is a
105	              -- PRESENCE TEST ONLY and alters nothing that is stored or shown.
106	              --
107	              -- NOT btrim(). PostgreSQL's one-argument btrim strips ORDINARY
108	              -- SPACES only, so a draft of tabs or newlines would have passed as
109	              -- writing while the design said it must not. The POSIX class is the
110	              -- predicate the design actually describes: does any non-whitespace
111	              -- character exist at all?
112	              (SELECT d.content ~ '[^[:space:]]'
113	                 FROM manuscript_working_drafts d
114	                WHERE d.manuscript_id = m.id) IS TRUE AS has_draft_writing,
115	
116	              -- Writing exists in EITHER lifecycle layer. Deliberately an OR and
117	              -- not the CASE the extent uses: an emptied draft over a Source that
118	              -- still holds the book is not "no writing".
119	              ((SELECT d.content ~ '[^[:space:]]'
120	                  FROM manuscript_working_drafts d
121	                 WHERE d.manuscript_id = m.id) IS TRUE
122	               OR EXISTS (SELECT 1 FROM manuscript_sections s
123	                           WHERE s.manuscript_id = m.id AND s.body ~ '[^[:space:]]'))
124	                AS has_writing,
125	
126	              -- ⭐ AUTHORSHIP: does the current draft diverge from the baseline
127	              -- every creation path writes as revision 1 ('Started writing' for a
128	              -- blank page, 'Initialized verbatim from source' for a seeded one)?
