130	              --
131	              -- ⛔ FAILS CLOSED. A draft with no revision 1 — a legacy row
132	              -- predating both creation paths — yields FALSE. A Work must not
133	              -- become continuable because its evidence is absent.
134	              --
135	              -- The length test is first so a genuine edit short-circuits before
136	              -- two long texts are compared; equal-length cases (a verbatim seed,
137	              -- a checkpoint) fall through to the content comparison, which is
138	              -- what actually decides them.
139	              (SELECT length(d.content) IS DISTINCT FROM length(r1.content)
140	                   OR d.content IS DISTINCT FROM r1.content
141	                 FROM manuscript_working_drafts d
142	                 JOIN working_draft_revisions r1
143	                   ON r1.draft_id = d.id AND r1.revision_number = 1
144	                WHERE d.manuscript_id = m.id) IS TRUE
145	                AS has_current_member_contribution
146	         FROM member_manuscripts m
147	        WHERE m.member_id = $1
148	        ORDER BY m.created_at DESC`,
