152	      manuscripts: result.rows.map((r) => ({
153	        id: r.id,
154	        title: r.title,
155	        createdAt: r.created_at,
156	        sectionCount: Number(r.section_count),
157	        charCount: Number(r.char_count),
158	        keepCount: Number(r.keep_count),
159	        lastMemberDraftActivityAt: r.last_written_at,
