172	const HEADING_SIGNALS: ReadonlySet<string> = new Set(['markdown', 'chapter', 'caps', 'member']);
173	
174	/** WS2-08A — coerce a confirmed section's depth fields; never throw. */
175	function classifyDepth(
176	  depth: unknown,
177	  signal: unknown,
178	): { depth: HeadingDepth | null; signal: HeadingSignal | null } {
179	  const d = depth === 1 || depth === 2 || depth === 3 ? depth : null;
180	  const sig = typeof signal === 'string' && HEADING_SIGNALS.has(signal) ? (signal as HeadingSignal) : null;
181	  // An explicit depth always names its cause; a caps/member boundary never carries one.
182	  if (d !== null && (sig === null || sig === 'caps')) return { depth: null, signal: sig };
183	  if (d === null && (sig === 'markdown' || sig === 'chapter')) return { depth: null, signal: null };
184	  return { depth: d, signal: sig };
185	}
