187	export async function POST(request: NextRequest) {
188	  if (process.env.CAPACITOR_BUILD) {
189	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
190	  }
191	  try {
192	    const memberId = await getMemberIdFromRequest(request);
193	    if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
194	
195	    let body: unknown;
196	    try {
197	      body = await request.json();
198	    } catch {
199	      return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
200	    }
201	    const { title, text, sections, sourceArrivalId, confirmedText } = (body ?? {}) as {
202	      title?: unknown;
203	      text?: unknown;
204	      sections?: unknown;
205	      sourceArrivalId?: unknown;
206	      /** Save step only: the exact text the member supplied, for a paste. */
207	      confirmedText?: unknown;
208	    };
209	
210	    if (typeof title !== 'string' || title.trim().length === 0) {
211	      return NextResponse.json({ error: 'title is required' }, { status: 400 });
212	    }
213	
214	    // Preview step: mechanical segmentation only; nothing is saved.
215	    if (typeof text === 'string') {
216	      if (text.trim().length === 0) {
217	        return NextResponse.json({ error: 'text is empty' }, { status: 400 });
218	      }
219	      if (text.length > MAX_TEXT_CHARS) {
220	        return NextResponse.json({ error: 'manuscript too large (2MB text max)' }, { status: 400 });
221	      }
222	      /* WS-01 — the segmentation runs under an omission control.
223	       *
224	       * This is where arriving text used to disappear: an orphan heading hit
225	       * the empty-body skip and was dropped, silently, before the member ever
226	       * saw the cuts. The control compares what arrived against what the cuts
227	       * account for, and reports rather than repairs — a segmentation that
228	       * loses text is a defect to be seen, not smoothed over. It is a log
229	       * marker and a response field, never a member-facing error, because the
230	       * member's own path must not become the place a machine defect surfaces. */
231	      const preview = segment(text);
232	      const omission = detectOmission(text, preview);
233	      if (!omission.lossless) {
234	        console.error(
235	          `[MAIA/press] SEGMENTATION LOSS { memberRef: ${memberRef(memberId)}, ${omissionMarker(omission)} }`,
236	        );
237	      }
238	      return NextResponse.json({ preview, lossless: omission.lossless });
239	    }
240	
241	    // Save step: member-confirmed sections.
242	    if (!Array.isArray(sections) || sections.length === 0) {
243	      return NextResponse.json(
244	        { error: 'Provide { title, text } to preview or { title, sections } to save' },
245	        { status: 400 },
246	      );
247	    }
248	    if (sections.length > MAX_SECTIONS) {
249	      return NextResponse.json({ error: `too many sections (max ${MAX_SECTIONS})` }, { status: 400 });
250	    }
251	    const clean: SectionInput[] = [];
252	    for (let i = 0; i < sections.length; i++) {
253	      const s = sections[i] as {
254	        heading?: unknown;
255	        body?: unknown;
256	        headingDepth?: unknown;
257	        headingSignal?: unknown;
258	      };
259	      if (typeof s?.body !== 'string' || s.body.trim().length === 0) continue;
260	      const heading = typeof s.heading === 'string' && s.heading.trim().length > 0 ? s.heading : null;
261	      /* WS2-08A — the depth the preview carried survives the member's
262	       * confirmation. Anything malformed reads as unclassified rather than
263	       * refusing the save: these fields describe the heading, they are not
264	       * custody of text, and a member must never lose a book to them. A
265	       * section with no heading has nothing to classify. */
266	      const { depth, signal } = heading ? classifyDepth(s.headingDepth, s.headingSignal) : { depth: null, signal: null };
267	      clean.push({
268	        position: clean.length,
269	        heading,
270	        body: s.body,
271	        headingDepth: depth,
272	        headingSignal: signal,
273	      });
274	    }
275	    if (clean.length === 0) {
276	      return NextResponse.json({ error: 'no non-empty sections' }, { status: 400 });
277	    }
278	
279	    const ms = await query<{ id: string }>(
280	      `INSERT INTO member_manuscripts (member_id, title) VALUES ($1, $2) RETURNING id`,
281	      [memberId, title.trim()],
282	    );
283	    const manuscriptId = ms.rows[0].id;
284	    for (const s of clean) {
285	      await query(
286	        `INSERT INTO manuscript_sections (manuscript_id, position, heading, body, heading_depth, heading_signal)
287	         VALUES ($1, $2, $3, $4, $5, $6)`,
288	        [manuscriptId, s.position, s.heading, s.body, s.headingDepth ?? null, s.headingSignal ?? null],
289	      );
290	    }
291	
292	    /* WS-01 — bind the manuscript to its arrival.
293	     *
294	     * Two paths, and the difference between them is provenance, not plumbing:
295	     *
296	     *   a file-backed import already has an arrival, taken into custody at
297	     *   ingest before the member could edit anything. It is claimed here.
298	     *
299	     *   a pasted or typed import has no artifact and must never be given one.
300	     *   Its authoritative source is the exact text the member supplied at THIS
301	     *   act — the confirmation — which is why it is recorded now rather than
302	     *   captured earlier from a textarea the member had not finished with.
303	     *
304	     * A manuscript whose arrival cannot be bound stays labelled
305	     * `legacy_interpreted_import` by the column default. It is not failed and
306	     * not deleted — the member's words are saved either way — but neither is it
307	     * allowed to claim a custody it does not have. */
308	    let custody = 'legacy_interpreted_import';
309	    try {
310	      if (typeof sourceArrivalId === 'string' && sourceArrivalId.length > 0) {
311	        if (await claimArrival(sourceArrivalId, manuscriptId, memberId)) {
312	          custody = 'source_custodied';
313	        }
314	      } else if (typeof confirmedText === 'string' && confirmedText.trim().length > 0) {
315	        const arrival = await recordSuppliedArrival({ memberId, sourceText: confirmedText });
316	        if (await claimArrival(arrival.id, manuscriptId, memberId)) {
317	          custody = 'source_custodied';
318	        }
319	      }
320	    } catch (err) {
321	      // Custody is additive: failing to record it must not lose the member's
322	      // manuscript, which is already saved. The label stays honest instead.
323	      console.error('[press/manuscripts] source custody binding failed', err);
324	    }
325	
326	    // Log marker: counts and provenance only, never content.
327	    console.log(
328	      `[MAIA/press] manuscript saved { memberRef: ${memberRef(memberId)}, ` +
329	        `manuscriptId: ${manuscriptId}, sections: ${clean.length}, custody: ${custody} }`,
330	    );
331	    return NextResponse.json(
332	      { id: manuscriptId, sectionCount: clean.length, sourceCustody: custody },
333	      { status: 201 },
334	    );
335	  } catch (err) {
336	    console.error('[press/manuscripts] POST error:', err);
337	    return NextResponse.json({ error: 'Failed to save manuscript' }, { status: 500 });
338	  }
339	}
340

