import { NextRequest, NextResponse } from 'next/server';
import { query } from '@/lib/db/postgres';
import { getMemberIdFromRequest } from '@/lib/auth/getMemberFromRequest';
import {
  segment,
  MAX_SECTIONS,
  type SectionInput,
  type HeadingDepth,
  type HeadingSignal,
} from '@/lib/manuscript/ingest/segment';
import { memberRef } from '@/lib/privacy/memberRef';
import { claimArrival, recordSuppliedArrival } from '@/lib/manuscript/source/arrivals';
import { detectOmission, omissionMarker } from '@/lib/manuscript/source/omission';

const MAX_TEXT_CHARS = 2_000_000; // ~a very long book; hard cap for sanity

export async function GET(request: NextRequest) {
  if (process.env.CAPACITOR_BUILD) {
    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
  }
  try {
    const memberId = await getMemberIdFromRequest(request);
    if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    const result = await query<{
      id: string;
      title: string | null;
      created_at: string;
      section_count: string;
      char_count: string;
      keep_count: string;
      last_written_at: string | null;
      draft_char_count: string | null;
      has_draft_writing: boolean;
      has_writing: boolean;
      has_current_member_contribution: boolean;
    }>(
      `SELECT m.id, m.title, m.created_at,
              (SELECT count(*) FROM manuscript_sections s WHERE s.manuscript_id = m.id) AS section_count,
              (SELECT coalesce(sum(length(s.body)), 0) FROM manuscript_sections s WHERE s.manuscript_id = m.id) AS char_count,
              (SELECT count(*) FROM manuscript_keeps k WHERE k.manuscript_id = m.id) AS keep_count,
              -- ⛔ DRAFT ACTIVITY — a member act, but NOT NECESSARILY WRITING.
              --
              -- ⚠️ CORRECTED 2026-09-08 (STUDIO-WRITING-PRESENCE-01). The
              -- previous version of this comment enumerated the writers to
              -- updated_at and concluded that the column advances only when
              -- the member actually writes. That enumeration was INCOMPLETE and
              -- the conclusion was FALSE:
              --
              --   draft/checkpoint/route.ts:145  UPDATE manuscript_working_drafts
              --      SET version, revision_count, updated_at, last_idempotency_*
              --      ⛔ and NO content.
              --
              -- So a member may import a book, let the draft be seeded verbatim,
              -- press "Keep a version", and advance BOTH updated_at and the
              -- revision trail without authoring a single character. The two
              -- signals are not independent evidence of authorship; they report
              -- the same weaker fact — that a post-creation draft act occurred.
              --
              -- What this column therefore establishes is MEMBER DRAFT ACTIVITY:
              -- saving, checkpointing, restoring, or editing. It does not
              -- establish writing, and nothing may render it as a writing time.
              -- Authorship is established below, by
              -- has_current_member_contribution, against the durable
              -- revision-1 baseline.
              --
              -- Kept as last_written_at on the wire only to avoid unrelated
              -- compatibility work. ⛔ It may not be used as authority for
              -- continuability and may not render as "written <when>".
              (SELECT CASE WHEN d.updated_at > d.created_at THEN d.updated_at END
                 FROM manuscript_working_drafts d
                WHERE d.manuscript_id = m.id) AS last_written_at,

              -- STUDIO-WRITING-PRESENCE-01 · three truths, none standing in for
              -- another. char_count above is SOURCE extent and stays that.
              (SELECT length(d.content) FROM manuscript_working_drafts d
                WHERE d.manuscript_id = m.id) AS draft_char_count,

              -- Substantive draft presence. Whitespace is not writing; this is a
              -- PRESENCE TEST ONLY and alters nothing that is stored or shown.
              --
              -- NOT btrim(). PostgreSQL's one-argument btrim strips ORDINARY
              -- SPACES only, so a draft of tabs or newlines would have passed as
              -- writing while the design said it must not. The POSIX class is the
              -- predicate the design actually describes: does any non-whitespace
              -- character exist at all?
              (SELECT d.content ~ '[^[:space:]]'
                 FROM manuscript_working_drafts d
                WHERE d.manuscript_id = m.id) IS TRUE AS has_draft_writing,

              -- Writing exists in EITHER lifecycle layer. Deliberately an OR and
              -- not the CASE the extent uses: an emptied draft over a Source that
              -- still holds the book is not "no writing".
              ((SELECT d.content ~ '[^[:space:]]'
                  FROM manuscript_working_drafts d
                 WHERE d.manuscript_id = m.id) IS TRUE
               OR EXISTS (SELECT 1 FROM manuscript_sections s
                           WHERE s.manuscript_id = m.id AND s.body ~ '[^[:space:]]'))
                AS has_writing,

              -- ⭐ AUTHORSHIP: does the current draft diverge from the baseline
              -- every creation path writes as revision 1 ('Started writing' for a
              -- blank page, 'Initialized verbatim from source' for a seeded one)?
              -- Nothing prunes revisions, so the baseline is durable.
              --
              -- ⛔ FAILS CLOSED. A draft with no revision 1 — a legacy row
              -- predating both creation paths — yields FALSE. A Work must not
              -- become continuable because its evidence is absent.
              --
              -- The length test is first so a genuine edit short-circuits before
              -- two long texts are compared; equal-length cases (a verbatim seed,
              -- a checkpoint) fall through to the content comparison, which is
              -- what actually decides them.
              (SELECT length(d.content) IS DISTINCT FROM length(r1.content)
                   OR d.content IS DISTINCT FROM r1.content
                 FROM manuscript_working_drafts d
                 JOIN working_draft_revisions r1
                   ON r1.draft_id = d.id AND r1.revision_number = 1
                WHERE d.manuscript_id = m.id) IS TRUE
                AS has_current_member_contribution
         FROM member_manuscripts m
        WHERE m.member_id = $1
        ORDER BY m.created_at DESC`,
      [memberId],
    );
    return NextResponse.json({
      manuscripts: result.rows.map((r) => ({
        id: r.id,
        title: r.title,
        createdAt: r.created_at,
        sectionCount: Number(r.section_count),
        charCount: Number(r.char_count),
        keepCount: Number(r.keep_count),
        lastMemberDraftActivityAt: r.last_written_at,
        draftCharCount: r.draft_char_count === null ? null : Number(r.draft_char_count),
        hasDraftWriting: r.has_draft_writing === true,
        hasWriting: r.has_writing === true,
        hasCurrentMemberContribution: r.has_current_member_contribution === true,
      })),
    });
  } catch (err) {
    console.error('[press/manuscripts] GET error:', err);
    return NextResponse.json({ error: 'Failed to load manuscripts' }, { status: 500 });
  }
}

const HEADING_SIGNALS: ReadonlySet<string> = new Set(['markdown', 'chapter', 'caps', 'member']);

/** WS2-08A — coerce a confirmed section's depth fields; never throw. */
function classifyDepth(
  depth: unknown,
  signal: unknown,
): { depth: HeadingDepth | null; signal: HeadingSignal | null } {
  const d = depth === 1 || depth === 2 || depth === 3 ? depth : null;
  const sig = typeof signal === 'string' && HEADING_SIGNALS.has(signal) ? (signal as HeadingSignal) : null;
  // An explicit depth always names its cause; a caps/member boundary never carries one.
  if (d !== null && (sig === null || sig === 'caps')) return { depth: null, signal: sig };
  if (d === null && (sig === 'markdown' || sig === 'chapter')) return { depth: null, signal: null };
  return { depth: d, signal: sig };
}

export async function POST(request: NextRequest) {
  if (process.env.CAPACITOR_BUILD) {
    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
  }
  try {
    const memberId = await getMemberIdFromRequest(request);
    if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    let body: unknown;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
    }
    const { title, text, sections, sourceArrivalId, confirmedText } = (body ?? {}) as {
      title?: unknown;
      text?: unknown;
      sections?: unknown;
      sourceArrivalId?: unknown;
      /** Save step only: the exact text the member supplied, for a paste. */
      confirmedText?: unknown;
    };

    if (typeof title !== 'string' || title.trim().length === 0) {
      return NextResponse.json({ error: 'title is required' }, { status: 400 });
    }

    // Preview step: mechanical segmentation only; nothing is saved.
    if (typeof text === 'string') {
      if (text.trim().length === 0) {
        return NextResponse.json({ error: 'text is empty' }, { status: 400 });
      }
      if (text.length > MAX_TEXT_CHARS) {
        return NextResponse.json({ error: 'manuscript too large (2MB text max)' }, { status: 400 });
      }
      /* WS-01 — the segmentation runs under an omission control.
       *
       * This is where arriving text used to disappear: an orphan heading hit
       * the empty-body skip and was dropped, silently, before the member ever
       * saw the cuts. The control compares what arrived against what the cuts
       * account for, and reports rather than repairs — a segmentation that
       * loses text is a defect to be seen, not smoothed over. It is a log
       * marker and a response field, never a member-facing error, because the
       * member's own path must not become the place a machine defect surfaces. */
      const preview = segment(text);
      const omission = detectOmission(text, preview);
      if (!omission.lossless) {
        console.error(
          `[MAIA/press] SEGMENTATION LOSS { memberRef: ${memberRef(memberId)}, ${omissionMarker(omission)} }`,
        );
      }
      return NextResponse.json({ preview, lossless: omission.lossless });
    }

    // Save step: member-confirmed sections.
    if (!Array.isArray(sections) || sections.length === 0) {
      return NextResponse.json(
        { error: 'Provide { title, text } to preview or { title, sections } to save' },
        { status: 400 },
      );
    }
    if (sections.length > MAX_SECTIONS) {
      return NextResponse.json({ error: `too many sections (max ${MAX_SECTIONS})` }, { status: 400 });
    }
    const clean: SectionInput[] = [];
    for (let i = 0; i < sections.length; i++) {
      const s = sections[i] as {
        heading?: unknown;
        body?: unknown;
        headingDepth?: unknown;
        headingSignal?: unknown;
      };
      if (typeof s?.body !== 'string' || s.body.trim().length === 0) continue;
      const heading = typeof s.heading === 'string' && s.heading.trim().length > 0 ? s.heading : null;
      /* WS2-08A — the depth the preview carried survives the member's
       * confirmation. Anything malformed reads as unclassified rather than
       * refusing the save: these fields describe the heading, they are not
       * custody of text, and a member must never lose a book to them. A
       * section with no heading has nothing to classify. */
      const { depth, signal } = heading ? classifyDepth(s.headingDepth, s.headingSignal) : { depth: null, signal: null };
      clean.push({
        position: clean.length,
        heading,
        body: s.body,
        headingDepth: depth,
        headingSignal: signal,
      });
    }
    if (clean.length === 0) {
      return NextResponse.json({ error: 'no non-empty sections' }, { status: 400 });
    }

    const ms = await query<{ id: string }>(
      `INSERT INTO member_manuscripts (member_id, title) VALUES ($1, $2) RETURNING id`,
      [memberId, title.trim()],
    );
    const manuscriptId = ms.rows[0].id;
    for (const s of clean) {
      await query(
        `INSERT INTO manuscript_sections (manuscript_id, position, heading, body, heading_depth, heading_signal)
         VALUES ($1, $2, $3, $4, $5, $6)`,
        [manuscriptId, s.position, s.heading, s.body, s.headingDepth ?? null, s.headingSignal ?? null],
      );
    }

    /* WS-01 — bind the manuscript to its arrival.
     *
     * Two paths, and the difference between them is provenance, not plumbing:
     *
     *   a file-backed import already has an arrival, taken into custody at
     *   ingest before the member could edit anything. It is claimed here.
     *
     *   a pasted or typed import has no artifact and must never be given one.
     *   Its authoritative source is the exact text the member supplied at THIS
     *   act — the confirmation — which is why it is recorded now rather than
     *   captured earlier from a textarea the member had not finished with.
     *
     * A manuscript whose arrival cannot be bound stays labelled
     * `legacy_interpreted_import` by the column default. It is not failed and
     * not deleted — the member's words are saved either way — but neither is it
     * allowed to claim a custody it does not have. */
    let custody = 'legacy_interpreted_import';
    try {
      if (typeof sourceArrivalId === 'string' && sourceArrivalId.length > 0) {
        if (await claimArrival(sourceArrivalId, manuscriptId, memberId)) {
          custody = 'source_custodied';
        }
      } else if (typeof confirmedText === 'string' && confirmedText.trim().length > 0) {
        const arrival = await recordSuppliedArrival({ memberId, sourceText: confirmedText });
        if (await claimArrival(arrival.id, manuscriptId, memberId)) {
          custody = 'source_custodied';
        }
      }
    } catch (err) {
      // Custody is additive: failing to record it must not lose the member's
      // manuscript, which is already saved. The label stays honest instead.
      console.error('[press/manuscripts] source custody binding failed', err);
    }

    // Log marker: counts and provenance only, never content.
    console.log(
      `[MAIA/press] manuscript saved { memberRef: ${memberRef(memberId)}, ` +
        `manuscriptId: ${manuscriptId}, sections: ${clean.length}, custody: ${custody} }`,
    );
    return NextResponse.json(
      { id: manuscriptId, sectionCount: clean.length, sourceCustody: custody },
      { status: 201 },
    );
  } catch (err) {
    console.error('[press/manuscripts] POST error:', err);
    return NextResponse.json({ error: 'Failed to save manuscript' }, { status: 500 });
  }
}

// Production web requires force-dynamic for runtime database access
// Capacitor builds: API routes are moved aside by scripts/build-capacitor.sh
export const dynamic = 'force-dynamic';

/**
 * Start writing — begin an expression that does not exist yet.
 *
 * THE ONE THING THIS ROUTE IS FOR: a member who has declared a Living Work and
 * has nothing written asks for a blank page. Before this existed, the Studio's
 * only door was "Import Manuscript" — so a writer who had named what they were
 * working on could do everything except write it. The room was usable only by
 * people who had already finished something somewhere else.
 *
 * WHY IT IS A SEPARATE ROUTE from POST /manuscripts. That route requires a
 * title and refuses an empty body ("no non-empty sections", "text is empty").
 * Those refusals are correct — they exist to reject junk imports — and
 * loosening them to serve a different gesture would weaken the import boundary
 * to buy something import does not need. Two gestures, two doors.
 *
 * WHAT IT REFUSES, and why each refusal is the point rather than an omission:
 *
 *   - **No invented title.** The manuscript is created with `title = NULL`. The
 *     route does not borrow the Living Work's name, does not generate
 *     "Untitled", does not use a date or a counter, and does not demand a name
 *     before the writer has written a word. The work's name and the
 *     expression's title are SEPARATE declarations (ledger D-16) and this route
 *     may only perform the one the member actually made — which is neither.
 *
 *   - **No source.** A blank page was not brought in from anywhere, so no
 *     `manuscript_sections` rows are written. Source means "what you brought
 *     in, unchanged". The one empty `manuscript_draft_sections` row created
 *     here is a writable slice, not Source provenance; its `source_section_id`
 *     is NULL. `base_source_hash` remains the hash of no source sections — the
 *     truthful statement that this draft descends from nothing.
 *
 *   - **No attachment.** Nothing is written to `living_work_expressions`. The
 *     member began writing; they did not declare that this expression belongs
 *     to that work. Attachment is its own act and its own slice.
 *
 *   - **No implicit creation.** This route runs only on an explicit member
 *     gesture. Declaring a work creates nothing. Arriving at the Studio creates
 *     nothing. The writer chooses Start writing, and that choice — nothing
 *     earlier — creates the place to write.
 */

import { NextRequest, NextResponse } from 'next/server';
import { query, transaction } from '@/lib/db/postgres';
import { getMemberIdFromRequest } from '@/lib/auth/getMemberFromRequest';
import { computeSourceHash } from '@/lib/manuscript/render/renderMemberBook';
import { partitionFromSections } from '@/lib/manuscript/draftSections';

export async function POST(request: NextRequest) {
  if (process.env.CAPACITOR_BUILD) {
    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
  }

  const memberId = await getMemberIdFromRequest(request);
  if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  try {
    // A blank page has no source, so the hash is the hash of no sections.
    const baseSourceHash = computeSourceHash([]);

    const created = await transaction(async (client) => {
      /**
       * DUPLICATE GUARD — proven necessary, not assumed.
       *
       * Two POSTs fired in parallel created two manuscripts (verified
       * 2026-08-02). A disabled button does not prevent that: a double tap, a
       * network retry, or a slow redirect can each issue a second request.
       *
       * The platform's existing idempotency convention (last_idempotency_key
       * on the target row, see manuscripts/[id]/draft) is built for UPDATES —
       * it needs a row that already exists to carry the key. There is no such
       * row when the act IS the creation, so it does not transfer.
       *
       * What does transfer is the meaning of the gesture: "Start writing"
       * asks for a blank page. If the member already has a blank page they
       * have not written in, handing them that one IS the correct answer —
       * not a workaround for a race. So this is find-or-create, and the
       * idempotency falls out of the semantics rather than being bolted on.
       *
       * Once they write a single character it is no longer blank, and the
       * next Start writing correctly makes a new one.
       *
       * The advisory lock is transaction-scoped and keyed to this member, so
       * two concurrent starts serialize instead of racing the SELECT. It is
       * held in the database rather than the UI because the UI is exactly the
       * layer that cannot make this promise.
       */
      await client.query(`SELECT pg_advisory_xact_lock(hashtext($1))`, [memberId]);

      const untouched = await client.query<{ id: string; draft_id: string }>(
        `SELECT m.id, d.id AS draft_id
           FROM member_manuscripts m
           JOIN manuscript_working_drafts d ON d.manuscript_id = m.id
          WHERE m.member_id = $1
            AND m.provenance = 'member_written'
            AND m.title IS NULL
            AND d.content = ''
            AND d.version = 1
            AND d.section_addressable_at IS NOT NULL
            AND NOT EXISTS (
              SELECT 1 FROM living_work_expressions e
               WHERE e.expression_type = 'manuscript'
                 AND e.expression_id = m.id
            )
          ORDER BY m.created_at ASC
          LIMIT 1`,
        [memberId]
      );
      if (untouched.rows.length > 0) {
        return {
          manuscriptId: untouched.rows[0].id,
          draftId: untouched.rows[0].draft_id,
          reused: true,
        };
      }

      const ms = await client.query<{ id: string }>(
        `INSERT INTO member_manuscripts (member_id, title, provenance)
         VALUES ($1, NULL, 'member_written')
         RETURNING id`,
        [memberId]
      );
      const manuscriptId = ms.rows[0].id;

      const draft = await client.query<{ id: string }>(
        `INSERT INTO manuscript_working_drafts
           (manuscript_id, member_id, content, base_source_hash, revision_count,
            section_addressable_at, section_conversion_version)
         VALUES ($1, $2, '', $3, 1, now(), 1)
         RETURNING id`,
        [manuscriptId, memberId, baseSourceHash]
      );

      /* The first blank writing surface is a DRAFT section, not a Source
         section. An empty section is explicitly lawful in the substrate and
         `source_section_id = NULL` says exactly what is true: these words did
         not arrive from an imported source. No chapter or heading is invented. */
      const section = await client.query<{ id: string }>(
        `INSERT INTO manuscript_draft_sections (draft_id, position, text, source_section_id)
         VALUES ($1, 0, '', NULL)
         RETURNING id`,
        [draft.rows[0].id],
      );
      const partition = partitionFromSections([{ id: section.rows[0].id, text: '' }]);

      // The first revision is the empty page itself, WITH the boundary that
      // exists at its birth, so restore/evidence never has to infer it later.
      await client.query(
        `INSERT INTO working_draft_revisions
           (draft_id, revision_number, content, saved_by, note, section_partition)
         VALUES ($1, 1, '', $2, 'Started writing', $3::jsonb)`,
        [draft.rows[0].id, memberId, JSON.stringify(partition)]
      );

      return { manuscriptId, draftId: draft.rows[0].id, reused: false };
    });

    // 200 when an existing untouched blank page was handed back, 201 when one
    // was actually created. The distinction is not cosmetic: a caller retrying
    // after a timeout must be able to tell "my request landed twice" from "my
    // request landed once", and the status is where that is said.
    return NextResponse.json(
      { id: created.manuscriptId, draftId: created.draftId, title: null },
      { status: created.reused ? 200 : 201 }
    );
  } catch (error) {
    console.error('[manuscripts/blank] create failed', error);
    return NextResponse.json({ error: 'Could not start writing' }, { status: 500 });
  }
}

/**
 * PROPOSAL-SUCCESSION-STORE-01 — the contract ⇄ database adapter.
 *
 * ⭐⭐ THE ACCEPTANCE QUESTION, AND THE ONLY ONE:
 *
 *   Can the durable database round-trip the already-proven contract without
 *   ADDING, LOSING, SYNTHESIZING or REINTERPRETING any fact?
 *
 * ⛔ SO THIS MODULE DECIDES NOTHING ABOUT SUCCESSION. It moves rows across the
 * boundary and hands them to `./succession`, which was proved on its own.
 * Anything here that re-derived lineage, order or the head would be a SECOND
 * implementation of succession — behind a database, where it is harder to see
 * and harder to falsify.
 *
 * ── ⛔ THE THREE PINNED CONSTRAINTS ────────────────────────────────────────
 *
 *   1  ⛔⛔ ORDER IS NEVER INFERRED FROM `authored_at`.
 *      There is no `ORDER BY authored_at` used as succession anywhere in this
 *      file. `supersedes` owns order. The head is `headOf()`.
 *
 *      ⚠️ AND THE TRAP ARRIVES BY INHERITANCE, not by carelessness:
 *      `editorialDecision/store.ts` defines "current" as the highest
 *      `event_index`, which is right for an event LOG. Copying that shape here
 *      means ordering by the nearest column we have — which is `authored_at` —
 *      and that is precisely the forbidden thing. Census §6.1.
 *
 *   2  ⛔ MEMBER IDENTITY IS ENFORCED AT THIS BOUNDARY.
 *      Knowing a chain UUID is not enough. `member_id` is inside the SQL
 *      predicate of every statement, never a filter applied after another
 *      member's row came back. A foreign chain reads as `null` — byte-identical
 *      to one that does not exist, which is the established convention
 *      (`readProposal`, `currentDecision`) and the point of it.
 *
 *   3  ⛔ THE `decision_chain_id` EVENT AMBIGUITY IS NOT RESOLVED HERE.
 *      The column names the governing decision LINEAGE. It does not prove which
 *      decision EVENT was current when the chain opened, and an editorial chain
 *      acquires successor events. So nothing here converts
 *
 *          decision lineage → latest event → "the ruling that governed this"
 *
 *      That is a contract-level decision if it is ever needed. Not an inference
 *      made at a persistence boundary from a timestamp.
 *
 * ── FAILURE STATES, kept apart as the project already decided ──────────────
 *
 *   database unavailable   ⭐ THROWS. `query()` propagates; this file adds no
 *                          blanket catch. ⛔ The `catch { return
 *                          refuse('write_failed') }` of
 *                          `revisionProposal/store.ts:211` is deliberately NOT
 *                          copied — it converts unavailability into a domain
 *                          refusal, which is the shape of the open S3
 *                          `unreachable` finding.
 *   absent / foreign       `null`, indistinguishable.
 *   a rule refused         a typed union, never an exception.
 */

import { query, transaction } from '@/lib/db/postgres';
import type { QueryResult, QueryResultRow } from 'pg';
import {
  appendVersion, validateChain,
} from './succession';
import type {
  EditorialRulingRef, LocusIdentity, ProposalChain, ProposalVersion,
  SuccessionRefusal, VersionAuthor,
} from './contract';

/* ══════════════════════════════════════════════════════════════════════════
   ROWS AND HYDRATION — the only place a column becomes a field.
   ══════════════════════════════════════════════════════════════════════════ */

interface ChainRow {
  id: string; member_id: string; work_id: string; draft_id: string;
  base_version: number | string; target_section_id: string; expected_text: string;
  decision_chain_id: string | null; opened_at: Date;
}

interface VersionRow {
  id: string; chain_id: string; author: VersionAuthor; formulation: string;
  rationale: string | null; supersedes: string | null; authored_at: Date;
}

const CHAIN_COLUMNS = `id, member_id, work_id, draft_id, base_version,
                       target_section_id, expected_text, decision_chain_id, opened_at`;

const VERSION_COLUMNS = `id, chain_id, author, formulation, rationale,
                         supersedes, authored_at`;

const hydrateChain = (r: ChainRow): ProposalChain => ({
  id: r.id,
  memberId: r.member_id,
  locus: {
    workId: r.work_id,
    draftId: r.draft_id,
    /* ⛔ pg returns integer/numeric as a string on some drivers. */
    baseVersion: Number(r.base_version),
    targetSectionId: r.target_section_id,
    expectedText: r.expected_text,
  },
  /* ⭐ ABSENT STAYS ABSENT. A chain no ruling governs has no `governedBy` key
     at all — not a key holding `null`, which would be a third state the
     contract has no word for. And ⛔ it hydrates as the LINEAGE REFERENCE and
     nothing else (constraint 3). */
  ...(r.decision_chain_id !== null
    ? { governedBy: { decisionChainId: r.decision_chain_id } satisfies EditorialRulingRef }
    : {}),
  openedAt: r.opened_at.toISOString(),
});

const hydrateVersion = (r: VersionRow): ProposalVersion => ({
  id: r.id,
  chainId: r.chain_id,
  supersedes: r.supersedes,
  /* ⚠️ THE ONE DELIBERATE NAME DIFFERENCE: contract `replacementText` ⇄ column
     `formulation`. This line is the only place the two are reconciled.
     ⛔ Read verbatim and never spread-guarded: `''` is a LEGITIMATE value — a
     deletion is a formulation. */
  replacementText: r.formulation,
  /* ⭐⭐ `!== null`, NOT TRUTHINESS.
     The project idiom is `...(r.x ? { x: r.x } : {})`. Here that would also
     swallow `''` into absence. The two coincide TODAY only because of the
     `rationale IS NULL OR length(btrim(rationale)) > 0` CHECK — in a different
     file. ⛔ A hydrator whose correctness depends on something it does not
     state is depending on luck. Census §6.5. */
  ...(r.rationale !== null ? { rationale: r.rationale } : {}),
  author: r.author,
  authoredAt: r.authored_at.toISOString(),
});

/* ══════════════════════════════════════════════════════════════════════════
   REFUSALS
   ══════════════════════════════════════════════════════════════════════════ */

/**
 * ⭐ THE STORE'S OWN REFUSALS, disjoint from `SuccessionRefusal`.
 *
 * ⛔ `chain_unknown` covers BOTH "no such chain" and "someone else's chain",
 * and that collapse is the protection, not a shortcut: a distinguishable
 * response would let a caller enumerate other members' chains by their refusal
 * shapes alone.
 */
export type StoreRefusal =
  | 'chain_unknown'
  /** The rows on disk do not form a valid chain. ⛔ Never repaired silently. */
  | 'chain_corrupt'
  /** Another append landed between the read and the write. ⛔ Never retried. */
  | 'simultaneous_append';

export type AppendRefusal = SuccessionRefusal | StoreRefusal;

export type AppendResult =
  | { readonly outcome: 'appended'; readonly version: ProposalVersion }
  | { readonly outcome: 'refused'; readonly reason: AppendRefusal };

/** A chain and every formulation in it. ⛔ Never only the head. */
export interface StoredChain {
  readonly chain: ProposalChain;
  readonly versions: readonly ProposalVersion[];
}

/* ══════════════════════════════════════════════════════════════════════════
   OPEN
   ══════════════════════════════════════════════════════════════════════════ */

export interface OpenChainInput {
  readonly locus: LocusIdentity;
  /** ⛔ The lineage reference, when one is known at open. Never set later. */
  readonly governedBy?: EditorialRulingRef;
}

/**
 * ⭐⭐ W5-4 · ANYTHING THAT CAN RUN ONE PARAMETERIZED STATEMENT — the pool, or
 * a single transaction's client. Structurally identical to `TransactionClient`
 * and deliberately NOT named after it: the pool is not a transaction.
 *
 * ⛔ IT EXISTS SO THERE IS EXACTLY ONE `INSERT INTO proposal_chains`. W5-4 must
 * open a chain and record MAIA's first observation as ONE durable act, which
 * needs the insert inside a caller's transaction — and the tempting way to get
 * that is to write the INSERT again in the editorial store. Two chain-insert
 * implementations is two places for the locus, the governing-ruling reference
 * and the minted identity to drift, behind a database, where it is hardest to
 * see. Census §6 is the same lesson about `readChain`.
 */
export interface SqlExecutor {
  query<T extends QueryResultRow = any>(
    sql: string, params?: any[]): Promise<QueryResult<T>>;
}

/**
 * The one chain INSERT. ⛔ Do not call this to "open a chain" — call
 * `openChain`, or `openChainWithInsight` when the chain and its first authored
 * editorial act must stand or fall together.
 */
export async function openChainWithExecutor(
  exec: SqlExecutor, memberId: string, input: OpenChainInput,
): Promise<ProposalChain> {
  const r = await exec.query<ChainRow>(
    `INSERT INTO proposal_chains
       (member_id, work_id, draft_id, base_version, target_section_id,
        expected_text, decision_chain_id)
     VALUES ($1, $2, $3, $4, $5, $6, $7)
     RETURNING ${CHAIN_COLUMNS}`,
    [memberId, input.locus.workId, input.locus.draftId, input.locus.baseVersion,
      input.locus.targetSectionId, input.locus.expectedText,
      input.governedBy?.decisionChainId ?? null]);
  return hydrateChain(r.rows[0]);
}

/**
 * Open a chain against one locus.
 *
 * ⛔ THIS AUTHORIZES NOTHING AND CHANGES NO WORK. It records the exact
 * characters a future authorization would be permitted to replace, and the
 * state of the Work that claim was made against.
 *
 * ⭐ The server mints the identity, following the decision store: a client that
 * could manufacture a stable id could also collide with one.
 *
 * ⭐ W5-4 · ITS PUBLIC SEMANTICS ARE UNCHANGED — same arguments, same statement,
 * same hydration, same autocommit-per-call behaviour. Only the executor moved
 * behind a parameter so a transaction can supply its own.
 */
export async function openChain(
  memberId: string, input: OpenChainInput,
): Promise<ProposalChain> {
  return openChainWithExecutor({ query }, memberId, input);
}

/* ══════════════════════════════════════════════════════════════════════════
   READ
   ══════════════════════════════════════════════════════════════════════════ */

/**
 * One member-owned chain and ALL of its versions.
 *
 * ⛔ NOT "the current version". `currentDecision`'s shape would return the head
 * and discard the intermediate formulations — which is the one thing this
 * substrate exists to preserve. Census §6.2.
 *
 * ⚠️ THE `ORDER BY` BELOW IS PRESENTATION ONLY, AND MUST STAY THAT WAY. It
 * makes the returned array deterministic for tests and diffs; it does NOT mean
 * anything about succession, and nothing downstream may read it as order.
 * `validateChain` and `headOf` work from `supersedes` on an unordered set — the
 * falsifier `timestamps do not determine lineage` proves exactly this by
 * storing contradictory timestamps.
 */
export async function readChain(
  memberId: string, chainId: string,
): Promise<StoredChain | null> {
  /* ⭐ member_id IN THE PREDICATE. A foreign chain returns zero rows here and
     is therefore reported as absent — the same `null` a missing chain gets. */
  const c = await query<ChainRow>(
    `SELECT ${CHAIN_COLUMNS} FROM proposal_chains
      WHERE id = $1 AND member_id = $2`, [chainId, memberId]);
  if (c.rows.length === 0) return null;

  const v = await query<VersionRow>(
    `SELECT ${VERSION_COLUMNS} FROM proposal_versions
      WHERE chain_id = $1
      ORDER BY id`, [chainId]);

  return {
    chain: hydrateChain(c.rows[0]),
    versions: v.rows.map(hydrateVersion),
  };
}

/* ══════════════════════════════════════════════════════════════════════════
   APPEND
   ══════════════════════════════════════════════════════════════════════════ */

/**
 * ⛔⛔ THIS FILE DOES NOT COMPUTE THE HEAD. IT DOES NOT EVEN ASK FOR IT.
 *
 * ⚠️ TWO FOUNDER REVIEWS ON 2026-09-14 CLOSED THIS IN TWO STEPS, and the second
 * went further than the first:
 *
 *   1  A local head-id helper here reproduced the pure head algorithm inside
 *      the persistence layer, under a comment asserting it "duplicates no
 *      logic". It quite literally did. ⭐ The proof was in the falsifier —
 *      mutation `M2` could mutate that helper ALONE, which is only possible
 *      when there are TWO INDEPENDENTLY FALSIFIABLE ANSWERS to "what is the
 *      head?". Two implementations that happened to agree. Repaired by
 *      importing the pure one.
 *
 *   2  ⭐⭐ BUT IMPORTING IT WAS STILL WRONG, because the QUESTION did not
 *      belong here. A store that asks "what is the head?" in order to fill in
 *      `supersedes` is SYNTHESIZING a succession fact the author never stated.
 *      See `AppendInput.supersedes`.
 *
 * ⭐ SO THE STRONGEST FORM OF THE LANE'S LAW IS THE ABSENCE OF THE QUESTION:
 *
 *    authored act ── supersedes = v4 ──▶ adapter ──▶ appendVersion()
 *                                                       │
 *                              durable head still v4 ───┤ lawful
 *                              durable head now  v5 ────┘ not_successor_of_head
 *
 * The database may determine whether a successor relationship is still lawful.
 * ⛔ It must never determine what relationship the author meant.
 */

/** ⛔ Never persisted. The database mints the real id. */
const PROVISIONAL_ID = '00000000-0000-0000-0000-000000000000';

const refuse = (reason: AppendRefusal) => ({ outcome: 'refused' as const, reason });

export interface AppendInput {
  /**
   * ⭐⭐ WHAT THIS FORMULATION SUCCEEDS — STATED BY THE AUTHOR, never searched
   * for here. `null` only when the author means this to be the chain's root.
   *
   * ⛔ FOUNDER REVIEW, 2026-09-14, MERGE BLOCKER. An earlier cut had the store
   * synthesize this from the current head after taking the row lock, and that
   * let LOCK ACQUISITION INVENT HISTORY. Two acts both authored against `v4`:
   *
   *     A takes the lock · reads v4 · store writes A.supersedes = v4 · commit
   *     B takes the lock · reads v5 · store writes B.supersedes = A   · commit
   *
   * The durable record then says `v4 → A → B` — but B never revised A. B was
   * authored against v4, and the machine's scheduling decided otherwise.
   *
   * ⚠️ And `23505` never fired, because `FOR UPDATE` had already serialized the
   * two calls before they could compete for the successor slot. This file's own
   * comment said retrying would make machine scheduling the ordering authority
   * over two authored acts — while the synthesized predecessor made it so
   * anyway, on the ordinary path.
   *
   * ⭐ THE EXISTING SUCCESSION FACT IS THE CONCURRENCY TOKEN. No CAS object is
   * added — census §6.4 stands on that; what changes is that `supersedes`
   * CROSSES THIS BOUNDARY rather than being discovered behind it. A stale
   * authored successor is then refused by the pure `appendVersion` as
   * `not_successor_of_head`, a refusal that already existed.
   */
  readonly supersedes: string | null;
  readonly author: VersionAuthor;
  readonly replacementText: string;
  readonly rationale?: string;
}

/**
 * Append one authored formulation.
 *
 * ⭐⭐ THE PURE FUNCTION IS THE FIRST AUTHORITY AND THE DATABASE IS THE SECOND,
 * and neither is decorative:
 *
 *   1  lock the chain           FOR UPDATE · member_id in the predicate
 *   2  read every version       inside that lock
 *   3  validateChain            ⛔ corrupt rows REFUSE; they are never repaired
 *   4  appendVersion            ⭐ is the AUTHORED predecessor still the head?
 *   5  INSERT                   the one-successor index refuses a race loser
 *
 * ⛔ Step 4 is where a lesser adapter would ask the database "what is the
 * latest row". ⭐⭐ THIS ONE NEVER ASKS: the candidate's predecessor ARRIVES
 * from the author (`AppendInput.supersedes`), and `appendVersion` decides only
 * whether that stated relationship is still lawful — `not_successor_of_head`
 * when the chain moved underneath it.
 *
 * ⛔ AND THERE IS NO `unchanged` OUTCOME. Re-recording an identical ruling is
 * not a new decision in the editorial-decision lane; here, two identical
 * formulations by different authors are TWO FORMULATIONS. Census §6.3.
 */
/**
 * ⭐⭐ THE SAME APPEND, ON A CALLER-SUPPLIED EXECUTOR — ER-R3.
 *
 * It exists so MAIA's turn, her ProposalVersion and the turn↔act binding are
 * ONE durable act. ⛔ There is still exactly ONE implementation of the append;
 * the public seam below opens a transaction and calls this.
 *
 * ⛔⛔ THE EXECUTOR CHANGES ATOMICITY, NEVER AUTHORITY. Every step below is
 * untouched: the chain is locked `FOR UPDATE` with `member_id` in the
 * predicate, every version is read inside that lock, `validateChain` refuses
 * corrupt rows, and ⭐ `appendVersion` still decides ONLY whether the
 * AUTHOR-STATED predecessor is still the head. The reread judges the stated
 * predecessor; ⛔ it never chooses a different one.
 */
export async function appendAuthoredVersionWithExecutor(
  tx: SqlExecutor, memberId: string, chainId: string, input: AppendInput,
): Promise<AppendResult> {
  return (async () => {
    /* 1 · The chain, locked, proven to be this member's in the same statement. */
    const c = await tx.query<ChainRow>(
      `SELECT ${CHAIN_COLUMNS} FROM proposal_chains
        WHERE id = $1 AND member_id = $2 FOR UPDATE`, [chainId, memberId]);
    if (c.rows.length === 0) return refuse('chain_unknown');
    const chain = hydrateChain(c.rows[0]);

    /* 2 · Every version, inside the lock. */
    const v = await tx.query<VersionRow>(
      `SELECT ${VERSION_COLUMNS} FROM proposal_versions
        WHERE chain_id = $1 ORDER BY id`, [chainId]);
    const versions = v.rows.map(hydrateVersion);

    /* 3 · ⛔ WHAT IS ON DISK MUST BE A CHAIN. If it is not, refuse and say so —
       an adapter that quietly worked around corrupt succession would be
       manufacturing a history nobody authored. */
    const valid = validateChain(chain, versions);
    if (!valid.ok) return refuse('chain_corrupt');

    /* 4 · ⭐ SUCCESSION DECIDED BY THE PURE FUNCTION. The candidate carries a
       provisional id; the row's real id is minted by the database and the
       returned version is hydrated from what was actually written. */
    const provisional: ProposalVersion = {
      id: PROVISIONAL_ID,
      chainId: chain.id,
      supersedes: input.supersedes,
      replacementText: input.replacementText,
      ...(input.rationale !== undefined ? { rationale: input.rationale } : {}),
      author: input.author,
      authoredAt: new Date(0).toISOString(),
    };
    const lawful = appendVersion(chain, versions, provisional);
    if (!lawful.ok) return refuse(lawful.reason);

    /* 5 · The write. The composite FK, the one-successor index, the one-root
       index and the rationale CHECK are all still in front of it. */
    try {
      const ins = await tx.query<VersionRow>(
        `INSERT INTO proposal_versions (chain_id, author, formulation, rationale, supersedes)
         VALUES ($1, $2, $3, $4, $5)
         RETURNING ${VERSION_COLUMNS}`,
        [chainId, input.author, input.replacementText,
          input.rationale ?? null, provisional.supersedes]);
      return { outcome: 'appended' as const, version: hydrateVersion(ins.rows[0]) };
    } catch (e) {
      /* ⛔ 23505 ONLY. Another append took this successor slot between the read
         and the write; the unique index refused the loser rather than letting
         one formulation overwrite another. ⛔ NO AUTOMATIC RETRY — retrying
         would make machine scheduling the ordering authority over two authored
         acts. Every other error RETHROWS: database unavailability is not a
         domain refusal. Census §6.6. */
      if ((e as { code?: string }).code === '23505') {
        return refuse('simultaneous_append');
      }
      throw e;
    }
  })();
}

/** The ordinary append, which opens its own transaction. Identical steps. */
export async function appendAuthoredVersion(
  memberId: string, chainId: string, input: AppendInput,
): Promise<AppendResult> {
  return transaction((tx) => appendAuthoredVersionWithExecutor(tx, memberId, chainId, input));
}

