1	/**
2	 * WRITERS-STUDIO-EXPERIENCE-REBUILD-01 — read model for the rebuilt room.
3	 *
4	 * This endpoint exists because the old Canvas split one fact across two APIs:
5	 * the writer needs draft-section ids to navigate/edit, while MAIA disclosure
6	 * and provenance need immutable Source ids. A bare `sectionId` cannot say
7	 * which namespace it belongs to. The rebuild receives both, by name, in one
8	 * ownership-scoped snapshot.
9	 *
10	 * READ ONLY. No conversion, save, relationship, reading, or model call occurs.
11	 */
12	
13	import { NextRequest, NextResponse } from 'next/server';
14	import { getMemberIdFromRequest } from '@/lib/auth/getMemberFromRequest';
15	import { query } from '@/lib/db/postgres';
16	import { splitStoredSection } from '@/lib/manuscript/sections/sectionProjection';
17	
18	export const dynamic = 'force-dynamic';
19	
20	interface DraftRow {
21	  id: string;
22	  version: string;
23	  updated_at: Date;
24	  section_addressable_at: Date | null;
25	}
26	
27	interface SectionRow {
28	  draft_section_id: string;
29	  source_section_id: string | null;
30	  position: number;
31	  text: string;
32	  heading: string | null;
33	  heading_depth: number | null;
34	  heading_signal: string | null;
35	}
36	
37	export async function GET(req: NextRequest) {
38	  const memberId = await getMemberIdFromRequest(req);
39	  if (!memberId) return NextResponse.json({ error: 'unauthenticated' }, { status: 401 });
40	
41	  const manuscriptId = req.nextUrl.searchParams.get('manuscriptId');
42	  if (!manuscriptId) {
43	    return NextResponse.json({ error: 'manuscriptId is required' }, { status: 400 });
44	  }
45	
46	  const manuscript = await query<{ id: string; title: string | null }>(
47	    `SELECT id, title FROM member_manuscripts WHERE id = $1 AND member_id = $2`,
48	    [manuscriptId, memberId],
49	  );
50	  if (manuscript.rows.length === 0) {
51	    return NextResponse.json({ error: 'not_found' }, { status: 404 });
52	  }
53	
54	  const draft = await query<DraftRow>(
55	    `SELECT id, version, updated_at, section_addressable_at
56	       FROM manuscript_working_drafts
57	      WHERE manuscript_id = $1 AND member_id = $2`,
58	    [manuscriptId, memberId],
59	  );
60	  if (draft.rows.length === 0) {
61	    return NextResponse.json({
62	      state: 'no_draft', manuscriptId, title: manuscript.rows[0].title,
63	    });
64	  }
65	  const d = draft.rows[0];
66	  if (d.section_addressable_at === null) {
67	    return NextResponse.json({
68	      state: 'continuous', manuscriptId, title: manuscript.rows[0].title,
69	      version: Number(d.version), updatedAt: d.updated_at.toISOString(),
70	    });
71	  }
72	
73	  const revision = await query<{ revision_number: number }>(
74	    `SELECT revision_number
75	       FROM working_draft_revisions
76	      WHERE draft_id = $1
77	      ORDER BY revision_number DESC
78	      LIMIT 1`,
79	    [d.id],
80	  );
81	  const draftRevision = revision.rows.length === 1
82	    ? Number(revision.rows[0]!.revision_number)
83	    : null;
84	
85	  const rows = await query<SectionRow>(
86	    `SELECT ds.id AS draft_section_id, ds.source_section_id, ds.position, ds.text,
87	            ms.heading, ms.heading_depth, ms.heading_signal
88	       FROM manuscript_draft_sections ds
89	       LEFT JOIN manuscript_sections ms ON ms.id = ds.source_section_id
90	      WHERE ds.draft_id = $1
91	      ORDER BY ds.position ASC`,
92	    [d.id],
93	  );
94	
95	  const sections = rows.rows.map((row) => {
96	    const split = splitStoredSection(row.text, row.heading);
97	    return {
98	      draftSectionId: row.draft_section_id,
99	      sourceSectionId: row.source_section_id,
100	      position: row.position,
101	      heading: row.heading,
102	      headingDepth: row.heading_depth,
103	      headingSignal: row.heading_signal,
104	      body: split ? split.body : row.text,
105	      headingPrefix: split ? split.headingPrefix : '',
106	      editable: split !== null,
107	    };
108	  });
109	
110	  return NextResponse.json({
111	    state: 'section_aware', manuscriptId, title: manuscript.rows[0].title,
112	    version: Number(d.version), draftRevision,
113	    updatedAt: d.updated_at.toISOString(), sections,
114	  });
115	}
