1	/**
2	 * Soullab Press — Working Draft (Author Environment R1 foundation)
3	 *
4	 * "This is where your manuscript lives."
5	 *
6	 * - Source stays immutable: POST initializes the draft VERBATIM from the
7	 *   manuscript's source sections; the sections themselves are never touched.
8	 *   base_source_hash records exactly which words the draft began from.
9	 * - Only the author writes the draft: every handler is member-scoped, with the
10	 *   same no-existence-leak 404 gate as the render route.
11	 * - Autosave (PUT) updates the draft in place; a checkpoint (PUT with
12	 *   checkpoint: true) additionally preserves an append-only revision.
13	 *
14	 * SECTION-ADDRESSABLE DRAFT LIVENESS (WS2-07 prerequisite, Option 3).
15	 *
16	 * A draft is section-addressable once `section_addressable_at` is set. From
17	 * that moment the SECTIONS are the writable truth and `content` is their
18	 * flattening — enforced at COMMIT by two deferred constraint triggers
19	 * (migration 20260830000001). Before this unit, no handler here wrote
20	 * `manuscript_draft_sections` at all, so a converted draft was not merely
21	 * stale on save: its next content-only write ABORTED at commit. It was
22	 * unwritable. That is the liveness defect this closes.
23	 *
24	 * Every rule about what may be written is decided in `lib/manuscript/
25	 * draftSections.ts` — a pure module with no database and no request — so a
26	 * defect in the contract is a unit-test failure rather than a 500 a member
27	 * discovers. This file does transport, authority and persistence; it does not
28	 * re-decide the contract, and it MUST NOT infer a boundary from text.
29	 *
30	 * ONE COMPOSITION AUTHORITY. The draft's starting text used to be composed by
31	 * a private `composeDraftText` here. It is gone: composition now happens once,
32	 * in `composeDraftSlices`, which returns the text AND the exact slice each
33	 * source section contributes. Two functions that merely agree today are two
34	 * chances to disagree tomorrow, and the disagreement would land as a
35	 * mis-assigned durable section identity.
36	 */
37	import { NextRequest, NextResponse } from 'next/server';
38	import { query, transaction } from '@/lib/db/postgres';
39	import { getMemberIdFromRequest } from '@/lib/auth/getMemberFromRequest';
40	import {
41	  computeSourceHash,
42	  type MemberBookSection,
43	} from '@/lib/manuscript/render/renderMemberBook';
44	import {
45	  composeDraftSlices,
46	  flattenSections,
47	  partitionFromSections,
48	  planConversion,
49	  validateSectionSave,
50	  type DraftSectionState,
51	  type SourceSection,
52	} from '@/lib/manuscript/draftSections';
53	import {
54	  conflictBody,
55	  payloadHash,
56	  normalizeVersion,
57	  precheck,
58	  readGuard,
59	  type DraftGuardRow,
60	} from '@/lib/manuscript/draftConcurrency';
61	
62	export const dynamic = 'force-dynamic';
63	
64	/** A source section as stored, with the identity conversion records as provenance. */
65	type SourceRow = SourceSection & MemberBookSection;
66	
67	/**
68	 * A finished HTTP answer raised from inside a transaction.
69	 *
70	 * ⛔ WHY THIS EXISTS AS A THROW. `transaction()` COMMITs when its callback
71	 * RETURNS and ROLLBACKs only when it THROWS. Returning a refusal from inside
72	 * one therefore commits whatever partial work preceded it while telling the
73	 * caller the request failed — the exact defect found in the first structure
74	 * adoption route, where a half-adopted outline was committed alongside a
75	 * failure response and locked the member out permanently. Every non-success
76	 * exit inside a transaction here is a throw, without exception.
77	 */
78	class DraftHttp extends Error {
79	  constructor(readonly status: number, readonly body: unknown) {
80	    super(`draft ${status}`);
81	  }
82	}
83	
84	function answer(e: unknown): NextResponse | null {
85	  return e instanceof DraftHttp ? NextResponse.json(e.body as object, { status: e.status }) : null;
86	}
87	
88	/** The draft's sections, in document order. */
89	async function loadSections(
90	  run: (sql: string, params?: unknown[]) => Promise<{ rows: DraftSectionState[] }>,
91	  draftId: string,
92	): Promise<DraftSectionState[]> {
93	  const r = await run(
94	    `SELECT id, text FROM manuscript_draft_sections WHERE draft_id = $1 ORDER BY position ASC`,
95	    [draftId],
96	  );
97	  return r.rows;
98	}
99	
100	/* ── POST — create, or convert an existing draft ──────────────────────────── */
101	
102	export async function POST(request: NextRequest, ctx: { params: Promise<{ id: string }> }) {
103	  if (process.env.CAPACITOR_BUILD) {
104	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
105	  }
106	  const { id } = await ctx.params;
107	  const memberId = await getMemberIdFromRequest(request);
108	  if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
109	
110	  /* A body is optional: creation sends none. `convert: true` is the EXPLICIT
111	     command that partitions an existing draft. It is a separate command on
112	     purpose — a conversion assigns durable identities that authored structure
113	     and developmental evidence both depend on, and D9 forbids smuggling that
114	     into an ordinary save. */
115	  let convert = false;
116	  try {
117	    const raw = await request.text();
118	    if (raw.trim().length > 0) {
119	      const parsed = JSON.parse(raw) as { convert?: unknown };
120	      convert = parsed?.convert === true;
121	    }
122	  } catch {
123	    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
124	  }
125	
126	  try {
127	    const ms = await query<{ id: string }>(
128	      `SELECT id FROM member_manuscripts WHERE id = $1 AND member_id = $2`,
129	      [id, memberId]
130	    );
131	    if (ms.rows.length === 0) {
132	      return NextResponse.json({ error: 'Not found' }, { status: 404 });
133	    }
134	
135	    const existing = await query<{
136	      id: string;
137	      content: string;
138	      version: string;
139	      section_addressable_at: string | null;
140	    }>(
141	      `SELECT id, content, version, section_addressable_at
142	         FROM manuscript_working_drafts WHERE manuscript_id = $1`,
143	      [id]
144	    );
145	
146	    const sections = await query<SourceRow>(
147	      `SELECT id, heading, body FROM manuscript_sections
148	        WHERE manuscript_id = $1 ORDER BY position ASC`,
149	      [id]
150	    );
151	
152	    if (existing.rows.length > 0) {
153	      if (!convert) {
154	        return NextResponse.json({ error: 'Draft already exists' }, { status: 409 });
155	      }
156	      return await convertExistingDraft(existing.rows[0], sections.rows);
157	    }
158	
159	    if (sections.rows.length === 0) {
160	      return NextResponse.json({ error: 'Manuscript has no sections' }, { status: 409 });
161	    }
162	
163	    /* D6 — a new draft is born section-addressable. Working draft, its
164	       partition and its immutable first revision are ONE transaction: a draft
165	       that exists without its sections is a draft the triggers will refuse to
166	       write, so the two must never be separately observable. */
167	    const { content, slices } = composeDraftSlices(sections.rows);
168	    const baseSourceHash = computeSourceHash(sections.rows);
169	
170	    const created = await transaction(async (tx) => {
171	      const draft = await tx.query(
172	        `INSERT INTO manuscript_working_drafts
173	           (manuscript_id, member_id, content, base_source_hash, revision_count,
174	            section_addressable_at, section_conversion_version)
175	         VALUES ($1, $2, $3, $4, 1, now(), 1)
176	         RETURNING id`,
177	        [id, memberId, content, baseSourceHash]
178	      );
179	      const draftId = draft.rows[0].id as string;
180	
181	      await tx.query(
182	        `INSERT INTO manuscript_draft_sections (draft_id, position, text, source_section_id)
183	         SELECT $1, ord - 1, t.text, t.source_id
184	           FROM unnest($2::text[], $3::uuid[]) WITH ORDINALITY AS t(text, source_id, ord)`,
185	        [draftId, slices.map((s) => s.text), slices.map((s) => s.sourceSectionId)]
186	      );
187	
188	      /* Read back BEFORE the revision is written: the ids are server-minted
189	         here, and the revision's partition is expressed in them. Writing the
190	         revision first would leave the draft's very first state unrecoverable
191	         at section granularity — the one revision every later comparison is
192	         measured from. */
193	      const written = await tx.query(
194	        `SELECT id, text FROM manuscript_draft_sections
195	          WHERE draft_id = $1 ORDER BY position ASC`,
196	        [draftId]
197	      );
198	      const sectionRows = written.rows as DraftSectionState[];
199	
200	      await tx.query(
201	        `INSERT INTO working_draft_revisions
202	           (draft_id, revision_number, content, saved_by, note, section_partition)
203	         VALUES ($1, 1, $2, $3, 'Initialized verbatim from source', $4::jsonb)`,
204	        [draftId, content, memberId, JSON.stringify(partitionFromSections(sectionRows))]
205	      );
206	
207	      return { draftId, sections: sectionRows };
208	    });
209	
210	    return NextResponse.json(
211	      {
212	        id: created.draftId,
213	        manuscriptId: id,
214	        baseSourceHash,
215	        revisionCount: 1,
216	        revisionId: 1,
217	        sectionAddressable: true,
218	        sections: created.sections,
219	        content,
220	      },
221	      { status: 201 }
222	    );
223	  } catch (error) {
224	    const typed = answer(error);
225	    if (typed) return typed;
226	    console.error('[manuscripts/draft] create failed', error);
227	    return NextResponse.json({ error: 'Failed to create draft' }, { status: 500 });
228	  }
229	}
230	
231	/**
232	 * Requirement A — convert an EXISTING draft, and only where the boundaries are
233	 * mechanically exact.
234	 *
235	 * ⛔ LOSSLESS IS BYTE EQUALITY, NOT RESEMBLANCE. `planConversion` admits the
236	 * conversion only when the draft's current content is byte-identical to the
237	 * flattening of the source-derived partition. Heading matching, similarity and
238	 * diff attribution are a different claim and are refused, typed, with zero
239	 * writes. A wrong boundary here is invisible at write time and silently
240	 * transfers a durable identity.
241	 */
242	async function convertExistingDraft(
243	  draft: { id: string; content: string; version: string; section_addressable_at: string | null },
244	  sourceRows: SourceRow[],
245	): Promise<NextResponse> {
246	  if (draft.section_addressable_at !== null) {
247	    return NextResponse.json(
248	      { error: 'Draft is already section-addressable', sectionAddressable: true },
249	      { status: 409 }
250	    );
251	  }
252	
253	  const plan = planConversion(draft.content, sourceRows);
254	  if (plan.status === 'refused') {
255	    return NextResponse.json({ refusal: plan.refusal, detail: plan.detail }, { status: 409 });
256	  }
257	
258	  const baseVersion = normalizeVersion(draft.version);
259	
260	  const result = await transaction(async (tx) => {
261	    /* The flag write comes FIRST so this transaction holds the draft row's
262	       lock before any section exists. A content save that committed between
263	       our read and here fails the version predicate and we abort — otherwise
264	       the partition would describe text the draft no longer holds, and the
265	       deferred trigger would surface it to the member as a 500. */
266	    const claimed = await tx.query(
267	      `UPDATE manuscript_working_drafts
268	          SET section_addressable_at = now(), section_conversion_version = version
269	        WHERE id = $1 AND version = $2 AND section_addressable_at IS NULL
270	        RETURNING version`,
271	      [draft.id, baseVersion]
272	    );
273	    if (claimed.rows.length === 0) {
274	      throw new DraftHttp(409, conflictBody('stale_base', baseVersion));
275	    }
276	
277	    await tx.query(
278	      `INSERT INTO manuscript_draft_sections (draft_id, position, text, source_section_id)
279	       SELECT $1, ord - 1, t.text, t.source_id
280	         FROM unnest($2::text[], $3::uuid[]) WITH ORDINALITY AS t(text, source_id, ord)`,
281	      [draft.id, plan.slices.map((s) => s.text), plan.slices.map((s) => s.sourceSectionId)]
282	    );
283	
284	    return await loadSections(tx.query, draft.id);
285	  });
286	
287	  /* ⛔ NO BACKFILL. The revisions written before this conversion were partitioned
288	     by nothing — their boundaries were never observed, and NULL says so. Stamping
289	     today's partition onto them would be an inference wearing a record's clothes,
290	     and restore would then rebuild sections the member never had. */
291	
292	  return NextResponse.json({
293	    id: draft.id,
294	    sectionAddressable: true,
295	    sections: result,
296	    content: draft.content,
297	    revisionId: baseVersion,
298	    converted: true,
299	  });
300	}
301	
302	/* ── GET — the D9 load contract ───────────────────────────────────────────── */
303	
304	export async function GET(request: NextRequest, ctx: { params: Promise<{ id: string }> }) {
305	  if (process.env.CAPACITOR_BUILD) {
306	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
307	  }
308	  const { id } = await ctx.params;
309	  const memberId = await getMemberIdFromRequest(request);
310	  if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
311	
312	  try {
313	    const draft = await query<{
314	      id: string;
315	      content: string;
316	      base_source_hash: string;
317	      revision_count: number;
318	      version: number;
319	      section_addressable_at: string | null;
320	      created_at: string;
321	      updated_at: string;
322	    }>(
323	      `SELECT id, content, base_source_hash, revision_count, version,
324	              section_addressable_at, created_at, updated_at
325	       FROM manuscript_working_drafts
326	       WHERE manuscript_id = $1 AND member_id = $2`,
327	      [id, memberId]
328	    );
329	    if (draft.rows.length === 0) {
330	      return NextResponse.json({ error: 'Not found' }, { status: 404 });
331	    }
332	    const row = draft.rows[0];
333	
334	    /* D9 — the client cannot hold section-native state unless the server first
335	       gives it the identities. It never invents or re-derives them, so a
336	       converted draft ALWAYS ships its sections; `content` travels alongside
337	       as a derived display projection, not as something the client may send
338	       back. `sectionAddressable` discriminates the two representations
339	       explicitly rather than leaving the client to sniff for a key. */
340	    const sectionAddressable = row.section_addressable_at !== null;
341	    const sections = sectionAddressable ? await loadSections(query, row.id) : null;
342	
343	    return NextResponse.json({
344	      id: row.id,
345	      manuscriptId: id,
346	      sectionAddressable,
347	      ...(sections ? { sections } : {}),
348	      content: row.content,
349	      baseSourceHash: row.base_source_hash,
350	      revisionCount: row.revision_count,
351	      revisionId: Number(row.version),
352	      createdAt: row.created_at,
353	      updatedAt: row.updated_at,
354	    });
355	  } catch (error) {
356	    console.error('[manuscripts/draft] get failed', error);
357	    return NextResponse.json({ error: 'Failed to load draft' }, { status: 500 });
358	  }
359	}
360	
361	/* ── PUT — the ordinary save ──────────────────────────────────────────────── */
362	
363	export async function PUT(request: NextRequest, ctx: { params: Promise<{ id: string }> }) {
364	  if (process.env.CAPACITOR_BUILD) {
365	    return NextResponse.json({ error: 'Not available in static build' }, { status: 501 });
366	  }
367	  const { id } = await ctx.params;
368	  const memberId = await getMemberIdFromRequest(request);
369	  if (!memberId) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
370	
371	  let body: unknown;
372	  try {
373	    body = await request.json();
374	  } catch {
375	    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
376	  }
377	  const { content, checkpoint, note } = body as {
378	    content?: unknown;
379	    checkpoint?: unknown;
380	    note?: unknown;
381	  };
382	  if (note !== undefined && note !== null && typeof note !== 'string') {
383	    return NextResponse.json({ error: 'note must be a string' }, { status: 400 });
384	  }
385	
386	  const guard = readGuard(body as Record<string, unknown>);
387	  if ('error' in guard) {
388	    return NextResponse.json({ error: guard.error }, { status: 400 });
389	  }
390	  const trimmedNote = typeof note === 'string' && note.trim().length > 0 ? note.trim() : null;
391	
392	  try {
393	    const current = await query<DraftGuardRow & { id: string; section_addressable_at: string | null }>(
394	      `SELECT id, version, section_addressable_at, last_idempotency_key, last_idempotency_op,
395	              last_idempotency_payload_hash, last_idempotency_response
396	         FROM manuscript_working_drafts
397	        WHERE manuscript_id = $1 AND member_id = $2`,
398	      [id, memberId]
399	    );
400	    if (current.rows.length === 0) {
401	      return NextResponse.json({ error: 'Not found' }, { status: 404 });
402	    }
403	
404	    if (current.rows[0].section_addressable_at !== null) {
405	      return await saveSectionAddressable({
406	        manuscriptId: id,
407	        memberId,
408	        draftId: current.rows[0].id,
409	        body: body as Record<string, unknown>,
410	        guard,
411	        checkpoint: checkpoint === true,
412	        note: trimmedNote,
413	      });
414	    }
415	
416	    /* An unconverted draft keeps its existing contract, unchanged — but a
417	       `sections` payload against it is a disagreement about WHICH draft this
418	       is, not a save. Answering with the draft's actual representation lets
419	       the client reload rather than guess; writing nothing is the point. */
420	    if (Object.prototype.hasOwnProperty.call(body as object, 'sections')) {
421	      return NextResponse.json(
422	        {
423	          error: 'this draft is not section-addressable; send content',
424	          sectionAddressable: false,
425	        },
426	        { status: 409 }
427	      );
428	    }
429	    if (typeof content !== 'string') {
430	      return NextResponse.json({ error: 'content must be a string' }, { status: 400 });
431	    }
432	
433	    const hash = payloadHash('save', { content, checkpoint: checkpoint === true, note: trimmedNote });
434	    const draftId = current.rows[0].id;
435	
436	    /* `version` is bigint, and node-postgres returns bigint as a STRING to
437	       avoid silent precision loss past 2^53. precheck compares it with !==
438	       against a number, so an unconverted "1" never equals 1 and EVERY write
439	       was rejected as stale_base. Coerced at the driver boundary, which is the
440	       only place the string form is real. */
441	    const guardRow = { ...current.rows[0], version: normalizeVersion(current.rows[0].version) };
442	    const decision = precheck(guardRow, 'save', guard.idempotencyKey, hash, guard.baseRevisionId);
443	    if (decision.kind === 'replay') {
444	      return NextResponse.json(decision.response as object);
445	    }
446	    if (decision.kind === 'conflict') {
447	      return NextResponse.json(conflictBody(decision.reason, decision.currentRevisionId), { status: 409 });
448	    }
449	
450	    // Compare-and-advance, recording the idempotency result in the SAME
451	    // statement. The version predicate is what makes this safe: a client that
452	    // raced us between the SELECT above and here matches zero rows. Recording
453	    // the key separately would leave a window in which a successful save
454	    // answers stale_base to its own retry. SET expressions read the OLD column
455	    // values, so version + 1 is exactly the version being written, and now()
456	    // is one timestamp for the whole statement.
457	    const updated = await query<{
458	      revision_count: number;
459	      version: number;
460	      last_idempotency_response: unknown;
461	    }>(
462	      `UPDATE manuscript_working_drafts
463	          SET content = $3,
464	              version = version + 1,
465	              revision_count = revision_count + CASE WHEN $5::boolean THEN 1 ELSE 0 END,
466	              updated_at = now(),
467	              last_idempotency_key = $6,
468	              last_idempotency_op = 'save',
469	              last_idempotency_payload_hash = $7,
470	              last_idempotency_response = jsonb_build_object(
471	                'revisionCount', revision_count + CASE WHEN $5::boolean THEN 1 ELSE 0 END,
472	                'revisionId', version + 1,
473	                'updatedAt', now(),
474	                'checkpointed', $5::boolean
475	              )
476	        WHERE manuscript_id = $1 AND member_id = $2 AND version = $4
477	      RETURNING revision_count, version, last_idempotency_response`,
478	      [id, memberId, content, guard.baseRevisionId, checkpoint === true, guard.idempotencyKey, hash]
479	    );
480	    if (updated.rows.length === 0) {
481	      const now = await query<{ version: number }>(
482	        `SELECT version FROM manuscript_working_drafts WHERE manuscript_id = $1 AND member_id = $2`,
483	        [id, memberId]
484	      );
485	      if (now.rows.length === 0) {
486	        return NextResponse.json({ error: 'Not found' }, { status: 404 });
487	      }
488	      return NextResponse.json(conflictBody('stale_base', normalizeVersion(now.rows[0].version)), { status: 409 });
489	    }
490	    const row = updated.rows[0];
491	
492	    if (checkpoint === true) {
493	      await query(
494	        `INSERT INTO working_draft_revisions (draft_id, revision_number, content, saved_by, note)
495	         VALUES ($1, $2, $3, $4, $5)`,
496	        [draftId, row.revision_count, content, memberId, trimmedNote]
497	      );
498	    }
499	
500	    // Reply with the stored record itself, so a first response and its replay
501	    // are byte-identical rather than merely equivalent.
502	    return NextResponse.json(row.last_idempotency_response as object);
503	  } catch (error) {
504	    const typed = answer(error);
505	    if (typed) return typed;
506	    console.error('[manuscripts/draft] save failed', error);
507	    return NextResponse.json({ error: 'Failed to save draft' }, { status: 500 });
508	  }
509	}
510	
511	/**
512	 * Requirement B — the section-native save.
513	 *
514	 * ONE TRANSACTION, because the round-trip invariant is checked at COMMIT: the
515	 * section rows and the derived content must land together or not at all.
516	 *
517	 * ⛔ THE TRIGGER IS THE BACKSTOP, NOT THE VALIDATOR. Every refusal is decided
518	 * by `validateSectionSave` before a single write, and content is DERIVED from
519	 * the accepted sections by `flattenSections`, so the invariant holds by
520	 * construction. If the trigger ever fires here, the contract is wrong — it is
521	 * not a way for the member to be told their save was malformed.
522	 */
523	async function saveSectionAddressable(args: {
524	  manuscriptId: string;
525	  memberId: string;
526	  draftId: string;
527	  body: Record<string, unknown>;
528	  guard: { idempotencyKey: string; baseRevisionId: number };
529	  checkpoint: boolean;
530	  note: string | null;
531	}): Promise<NextResponse> {
532	  const { manuscriptId, memberId, draftId, body, guard, checkpoint, note } = args;
533	
534	  const result = await transaction(async (tx) => {
535	    /* Read under the row lock. The section identities the payload is judged
536	       against must be the ones the write will land on, not the ones that were
537	       true a moment ago. */
538	    const locked = await tx.query(
539	      `SELECT version, last_idempotency_key, last_idempotency_op,
540	              last_idempotency_payload_hash, last_idempotency_response
541	         FROM manuscript_working_drafts
542	        WHERE id = $1 AND member_id = $2
543	        FOR UPDATE`,
544	      [draftId, memberId]
545	    );
546	    if (locked.rows.length === 0) {
547	      throw new DraftHttp(404, { error: 'Not found' });
548	    }
549	
550	    const currentSections = await loadSections(tx.query, draftId);
551	    const check = validateSectionSave(body, currentSections.map((s) => s.id));
552	    if (!check.ok) {
553	      /* Typed, zero writes, and never a database exception wearing a 500.
554	         The transaction is rolled back by the throw; nothing has been written
555	         before this point in any case. */
556	      throw new DraftHttp(409, { refusal: check.refusal, ...(check.detail ? { detail: check.detail } : {}) });
557	    }
558	    const sections = check.value;
559	
560	    /* Content is derived here and only here. The client never sends it, so
561	       there is no second claim about the same text to reconcile. */
562	    const content = flattenSections(sections);
563	
564	    /* The hash covers the SECTION payload, not the derived content: two
565	       different partitions can flatten to the same characters, and an
566	       idempotency key must bind to exactly one request body. */
567	    const hash = payloadHash('save', { sections, checkpoint, note });
568	
569	    const guardRow = {
570	      ...(locked.rows[0] as DraftGuardRow),
571	      version: normalizeVersion((locked.rows[0] as DraftGuardRow).version),
572	    };
573	    const decision = precheck(guardRow, 'save', guard.idempotencyKey, hash, guard.baseRevisionId);
574	    if (decision.kind === 'replay') {
575	      /* A success, but one that must write nothing. Raised rather than
576	         returned so the transaction rolls back instead of committing. */
577	      throw new DraftHttp(200, decision.response);
578	    }
579	    if (decision.kind === 'conflict') {
580	      throw new DraftHttp(409, conflictBody(decision.reason, decision.currentRevisionId));
581	    }
582	
583	    const updated = await tx.query(
584	      `UPDATE manuscript_working_drafts
585	          SET content = $3,
586	              version = version + 1,
587	              revision_count = revision_count + CASE WHEN $5::boolean THEN 1 ELSE 0 END,
588	              updated_at = now(),
589	              last_idempotency_key = $6,
590	              last_idempotency_op = 'save',
591	              last_idempotency_payload_hash = $7,
592	              last_idempotency_response = jsonb_build_object(
593	                'revisionCount', revision_count + CASE WHEN $5::boolean THEN 1 ELSE 0 END,
594	                'revisionId', version + 1,
595	                'updatedAt', now(),
596	                'checkpointed', $5::boolean
597	              )
598	        WHERE manuscript_id = $1 AND member_id = $2 AND version = $4
599	      RETURNING revision_count, version, last_idempotency_response`,
600	      [manuscriptId, memberId, content, guard.baseRevisionId, checkpoint, guard.idempotencyKey, hash]
601	    );
602	    if (updated.rows.length === 0) {
603	      throw new DraftHttp(409, conflictBody('stale_base', guardRow.version));
604	    }
605	
606	    /* Positions do not move: the payload was proven complete, unique and in
607	       current order, so every id maps onto the row it already occupies. This
608	       endpoint cannot change topology, and this statement cannot either — it
609	       writes text and nothing else. */
610	    const written = await tx.query(
611	      `UPDATE manuscript_draft_sections s
612	          SET text = v.text, updated_at = now()
613	         FROM (SELECT unnest($2::uuid[]) AS id, unnest($3::text[]) AS text) v
614	        WHERE s.id = v.id AND s.draft_id = $1`,
615	      [draftId, sections.map((s) => s.id), sections.map((s) => s.text)]
616	    );
617	    if (written.rowCount !== sections.length) {
618	      throw new DraftHttp(409, { refusal: 'unknown_section_id', detail: 'a section changed during the save' });
619	    }
620	
621	    /* D7 — the checkpoint still preserves the flattened whole draft in the
622	       append-only revision store, inside this same transaction. That store is
623	       the one BUILD-07A will locate evidence into; a checkpoint that could
624	       commit without its section write would break that locator. */
625	    if (checkpoint) {
626	      /* The partition is frozen FROM THE SECTIONS THIS SAVE ACCEPTED, not
627	         re-derived from the content afterwards. Re-deriving would be a second
628	         claim about the same boundaries, and the two could differ exactly
629	         where it matters least visibly. */
630	      await tx.query(
631	        `INSERT INTO working_draft_revisions
632	           (draft_id, revision_number, content, saved_by, note, section_partition)
633	         VALUES ($1, $2, $3, $4, $5, $6::jsonb)`,
634	        [draftId, updated.rows[0].revision_count, content, memberId, note,
635	         JSON.stringify(partitionFromSections(sections))]
636	      );
637	    }
638	
639	    return updated.rows[0].last_idempotency_response;
640	  });
641	
642	  return NextResponse.json(result as object);
643	}
644

