162	}): Promise<
163	  | { readonly ok: true; readonly relationship: EditorialRelationshipCustody }
164	  | { readonly ok: false; readonly reason: RelationshipCustodyRefusal }
165	> {
166	  try {
167	    return await transaction(async (tx) => {
168	      const work = await tx.query<{ id: string }>(
169	        `SELECT id FROM living_works
170	          WHERE id = $1 AND member_id = $2
171	          FOR KEY SHARE`,
172	        [input.livingWorkId, input.memberId],
173	      );
174	      if (work.rows.length !== 1) throw new RelationshipCustodyRefused('work_not_owned');
175	
176	      const manuscript = await tx.query<{ id: string }>(
177	        `SELECT id FROM member_manuscripts
178	          WHERE id = $1 AND member_id = $2
179	          FOR KEY SHARE`,
180	        [input.manuscriptId, input.memberId],
181	      );
182	      if (manuscript.rows.length !== 1) throw new RelationshipCustodyRefused('manuscript_not_owned');
183	
184	      const declaration = await tx.query<{ id: string }>(
185	        `SELECT id FROM living_work_expressions
186	          WHERE living_work_id = $1
187	            AND expression_type = 'manuscript'
188	            AND expression_id = $2
189	            AND declared_by = $3
190	          FOR KEY SHARE`,
191	        [input.livingWorkId, input.manuscriptId, input.memberId],
192	      );
193	      if (declaration.rows.length !== 1) {
194	        throw new RelationshipCustodyRefused('current_declaration_unavailable');
195	      }
196	
197	      const created = await tx.query<RelationshipRow>(
198	        `INSERT INTO writer_editorial_relationships
199	           (member_id, living_work_id, manuscript_id, creation_expression_id, contract_version)
200	         VALUES ($1, $2, $3, $4, $5)
201	         RETURNING id, member_id, living_work_id, manuscript_id,
202	                   creation_expression_id, contract_version, created_at`,
203	        [input.memberId, input.livingWorkId, input.manuscriptId,
204	         declaration.rows[0]!.id, A2_RELATIONSHIP_CONTRACT_VERSION],
205	      );
206	      return { ok: true as const, relationship: mapRelationship(created.rows[0]!) };
207	    });
208	  } catch (error) {
209	    if (error instanceof RelationshipCustodyRefused) {
210	      return { ok: false, reason: error.reason };
211	    }
212	    throw error;
213	  }
214	}
