426	    t => Number(t.turn_index) === input.maiaTurnIndex && t.speaker === 'maia',
427	  );
428	  if (!member || !maia) throw new RelationshipCustodyRefused('editorial_child_invalid');
429	}
430	async function validateReviewChild(
431	  tx: TransactionClient,
432	  prepared: PreparedRelationshipAppend,
433	  input: {
434	    threadId: string; maiaTurnIndex: number; authorizationId: string;
435	    readingId: string; observationKey: string;
436	  },
437	): Promise<void> {
438	  const r = await tx.query<{
439	    completed_at: Date | null; completion_ref: string | null; speaker: string;
440	  }>(
441	    `SELECT c.completed_at, c.completion_ref, t.speaker
442	       FROM ask_authorization_acts a
443	       JOIN ask_authorization_consumptions c ON c.act_id = a.id
444	       JOIN ask_threads th ON th.id = a.thread_id
445	       JOIN ask_turns t
446	         ON t.thread_id = a.thread_id
447	        AND t.turn_index = $6
448	      WHERE a.id = $1
449	        AND a.member_id = $2
450	        AND a.manuscript_id = $3
451	        AND a.thread_id = $4
452	        AND a.reading_id = $5
453	        AND a.observation_key = $7
454	        AND th.member_id = $2
455	        AND th.manuscript_id = $3
456	        AND th.reading_identity ->> 'kind' = 'review_discuss_r2_1'
457	        AND th.reading_identity ->> 'readingId' = $5::text
458	        AND th.reading_identity ->> 'observationKey' = $7`,
459	    [input.authorizationId, prepared.memberId, prepared.manuscriptId,
460	     input.threadId, input.readingId, input.maiaTurnIndex, input.observationKey],
461	  );
462	  if (r.rows.length !== 1) throw new RelationshipCustodyRefused('review_child_invalid');
463	  const row = r.rows[0]!;
464	  if (
465	    row.completed_at === null ||
466	    row.completion_ref !== `${input.threadId}:${input.maiaTurnIndex}` ||
467	    row.speaker !== 'maia'
468	  ) {
469	    throw new RelationshipCustodyRefused('review_child_invalid');
470	  }
471	}
472	
473	async function recoverInsertedEpisode(
474	  tx: TransactionClient,
475	  relationshipId: string,
476	  child: { kind: 'EDITORIAL_TURN'; threadId: string; maiaTurnIndex: number }
477	    | { kind: 'REVIEW_DISCUSS'; authorizationId: string },
478	): Promise<{ id: string; sequence: number }> {
479	  const found = child.kind === 'EDITORIAL_TURN'
480	    ? await existingEditorialEpisode(tx, child.threadId, child.maiaTurnIndex)
481	    : await existingReviewEpisode(tx, child.authorizationId);
482	  if (!found) throw new RelationshipCustodyRefused('sequence_conflict');
483	  if (found.relationship_id !== relationshipId) {
484	    throw new RelationshipCustodyRefused('child_already_attached_elsewhere');
485	  }
486	  return { id: found.id, sequence: Number(found.sequence) };
487	}
488	export async function appendEditorialEpisodeWithClient(
489	  tx: TransactionClient,
490	  prepared: PreparedRelationshipAppend,
491	  input: {
492	    threadId: string;
493	    proposalChainId: string;
494	    memberTurnIndex: number;
495	    maiaTurnIndex: number;
496	    manuscriptLocusScope: ManuscriptLocusScope;
497	  },
498	): Promise<{ readonly id: string; readonly sequence: number; readonly existing: boolean }> {
499	  const before = await existingEditorialEpisode(tx, input.threadId, input.maiaTurnIndex);
500	  if (before) {
501	    if (before.relationship_id !== prepared.relationshipId) {
502	      throw new RelationshipCustodyRefused('child_already_attached_elsewhere');
503	    }
504	    return { id: before.id, sequence: Number(before.sequence), existing: true };
505	  }
506	
507	  await validateEditorialChild(tx, prepared, input);
508	  const sequence = await nextSequence(tx, prepared.relationshipId);
509	  const inserted = await tx.query<{ id: string; sequence: number }>(
510	    `INSERT INTO writer_editorial_relationship_episodes
511	       (relationship_id, sequence, child_kind, manuscript_scope_requested, manuscript_scope_executed,
512	        temporal_posture, history_policy, continuation_authorized,
513	        authority_class, carry_policy,
514	        editorial_thread_id, editorial_proposal_chain_id,
515	        editorial_member_turn_index, editorial_maia_turn_index)
516	     VALUES
517	       ($1, $2, 'EDITORIAL_TURN', $3, $3,
518	        'CURRENT_FROZEN_LOCUS', 'CHILD_LOCAL_MULTI_TURN', TRUE,
519	        'EDITORIAL_CHAIN', 'PRESENTATION_ONLY',
520	        $4, $5, $6, $7)
521	     ON CONFLICT DO NOTHING
522	     RETURNING id, sequence`,
523	    [prepared.relationshipId, sequence, input.manuscriptLocusScope, input.threadId,
524	     input.proposalChainId, input.memberTurnIndex, input.maiaTurnIndex],
525	  );
526	  if (inserted.rows.length === 1) {
527	    return { id: inserted.rows[0]!.id, sequence: Number(inserted.rows[0]!.sequence), existing: false };
528	  }
529	  const recovered = await recoverInsertedEpisode(tx, prepared.relationshipId, {
530	    kind: 'EDITORIAL_TURN', threadId: input.threadId, maiaTurnIndex: input.maiaTurnIndex,
531	  });
532	  return { ...recovered, existing: true };
533	}
534	export async function appendReviewDiscussEpisodeWithClient(
535	  tx: TransactionClient,
536	  prepared: PreparedRelationshipAppend,
537	  input: {
538	    threadId: string;
539	    maiaTurnIndex: number;
540	    authorizationId: string;
541	    readingId: string;
542	    observationKey: string;
543	  },
544	): Promise<{ readonly id: string; readonly sequence: number; readonly existing: boolean }> {
545	  const before = await existingReviewEpisode(tx, input.authorizationId);
546	  if (before) {
547	    if (before.relationship_id !== prepared.relationshipId) {
548	      throw new RelationshipCustodyRefused('child_already_attached_elsewhere');
549	    }
550	    return { id: before.id, sequence: Number(before.sequence), existing: true };
551	  }
552	
553	  await validateReviewChild(tx, prepared, input);
554	  const sequence = await nextSequence(tx, prepared.relationshipId);
555	  const inserted = await tx.query<{ id: string; sequence: number }>(
556	    `INSERT INTO writer_editorial_relationship_episodes
557	       (relationship_id, sequence, child_kind, manuscript_scope_requested, manuscript_scope_executed,
558	        temporal_posture, history_policy, continuation_authorized,
559	        authority_class, carry_policy,
560	        review_thread_id, review_maia_turn_index, review_authorization_id,
561	        review_reading_id, review_observation_key)
562	     VALUES
563	       ($1, $2, 'REVIEW_DISCUSS', NULL, NULL,
564	        'AS_READ', 'NONE', FALSE,
565	        'R2_DISCLOSURE', 'PRESENTATION_ONLY',
566	        $3, $4, $5, $6, $7)
567	     ON CONFLICT DO NOTHING
568	     RETURNING id, sequence`,
569	    [prepared.relationshipId, sequence, input.threadId,
570	     input.maiaTurnIndex, input.authorizationId, input.readingId, input.observationKey],
571	  );
572	  if (inserted.rows.length === 1) {
573	    return { id: inserted.rows[0]!.id, sequence: Number(inserted.rows[0]!.sequence), existing: false };
574	  }
575	  const recovered = await recoverInsertedEpisode(tx, prepared.relationshipId, {
576	    kind: 'REVIEW_DISCUSS', authorizationId: input.authorizationId,
577	  });
578	  return { ...recovered, existing: true };
579	}
580	
581	/**
582	 * Convenience wrappers for an already-completed child in the SAME transaction.
583	 * Future live A2 integration should prefer prepareRelationshipForAppendWithClient
584	 * before writing the child completion, then call the append function afterward.
585	 */
586	export async function appendExistingEditorialEpisodeWithClient(
587	  tx: TransactionClient,
588	  input: {
589	    memberId: string; relationshipId: string; threadId: string; proposalChainId: string;
590	    memberTurnIndex: number; maiaTurnIndex: number; manuscriptLocusScope: ManuscriptLocusScope;
591	  },
592	) {
593	  const existing = await existingEditorialEpisode(tx, input.threadId, input.maiaTurnIndex);
594	  if (existing) {
595	    if (existing.relationship_id !== input.relationshipId) {
596	      throw new RelationshipCustodyRefused('child_already_attached_elsewhere');
597	    }
598	    return { id: existing.id, sequence: Number(existing.sequence), existing: true as const };
599	  }
600	  const prepared = await prepareRelationshipForAppendWithClient(tx, input);
601	  return appendEditorialEpisodeWithClient(tx, prepared, input);
602	}
603	export async function appendExistingReviewDiscussEpisodeWithClient(
604	  tx: TransactionClient,
605	  input: {
606	    memberId: string; relationshipId: string; threadId: string; maiaTurnIndex: number;
607	    authorizationId: string; readingId: string; observationKey: string;
608	  },
609	) {
610	  const existing = await existingReviewEpisode(tx, input.authorizationId);
611	  if (existing) {
612	    if (existing.relationship_id !== input.relationshipId) {
613	      throw new RelationshipCustodyRefused('child_already_attached_elsewhere');
614	    }
615	    return { id: existing.id, sequence: Number(existing.sequence), existing: true as const };
616	  }
617	  const prepared = await prepareRelationshipForAppendWithClient(tx, input);
618	  return appendReviewDiscussEpisodeWithClient(tx, prepared, input);
619	}
