79	/**
80	 * ⭐⭐ ONE DURABLE ACT. The chain and the conversation about it are opened
81	 * together or not at all — the W5-4 law: *failure may leave neither half
82	 * pretending the other happened.*
83	 */
84	export async function openEditorialRelationship(
85	  input: OpenEditorialInput,
86	): Promise<OpenEditorialResult> {
