91	 * Rebuild-only passage door. The member names coordinates, never manuscript
92	 * prose. The server rereads the section under ownership, verifies that the
93	 * draft has not advanced since selection, derives the exact characters, and
94	 * opens the same governed chain/thread pair the section door opens.
95	 */
96	export async function openEditorialRelationshipAtSelection(
97	  input: OpenEditorialSelectionInput,
98	): Promise<OpenEditorialResult> {
99	  return openEditorialRelationshipResolved(input, {
100	    range: input.range, revisionNumber: input.revisionNumber,
101	  });
102	}
