104	async function openEditorialRelationshipResolved(
105	  input: OpenEditorialInput,
106	  selection: { readonly range: EditorialSelectionRange; readonly revisionNumber: number } | null,
107	): Promise<OpenEditorialResult> {
108	  const memberId = input.identity.memberId;
109	  try {
110	    return await transaction(async (tx) => {
111	      const s = await tx.query<{
112	        draft_id: string; manuscript_id: string; revision_count: number; draft_version: string;
113	        text: string; heading: string | null;
114	      }>(
115	        `SELECT s.draft_id, d.manuscript_id, d.revision_count, d.version AS draft_version,
116	                s.text, ms.heading
117	           FROM manuscript_draft_sections s
118	           JOIN manuscript_working_drafts d ON d.id = s.draft_id
119	           LEFT JOIN manuscript_sections ms ON ms.id = s.source_section_id
120	          WHERE s.id = $1 AND d.member_id = $2`,
121	        [input.sectionId, memberId]);
122	      if (s.rows.length === 0) throw new OpenRefused('section_not_found');
123	      const row = s.rows[0]!;
124	
125	      const split = splitStoredSection(row.text, row.heading);
126	      if (!split) throw new OpenRefused('section_unprojectable');
127	      if (split.body.length === 0) throw new OpenRefused('section_has_no_body');
128	
129	      let expectedText = split.body;
130	      if (selection) {
131	        if (!Number.isInteger(selection.revisionNumber)
132	            || Number(row.draft_version) !== selection.revisionNumber) {
133	          throw new OpenRefused('selection_stale');
134	        }
135	        const projected = projectEditorialSelection(split.body, selection.range);
136	        if (!projected.ok) {
137	          const reason = projected.reason === 'selection_ambiguous'
138	            ? 'selection_ambiguous' : 'selection_invalid';
139	          throw new OpenRefused(reason);
140	        }
141	        expectedText = projected.text;
142	      }
143	
144	      const chain = await openChainWithExecutor(tx, memberId, {
145	        locus: {
146	          workId: row.manuscript_id,
147	          draftId: row.draft_id,
148	          baseVersion: Number(row.revision_count),
149	          targetSectionId: input.sectionId,
150	          locusScopeKind: selection === null ? 'section' : 'passage',
151	          expectedText,
152	        },
153	      });
