159	         VALUES ($1, $2, NULL, NULL, $3, 'author', $4)
160	         RETURNING id`,
161	        [row.manuscript_id, memberId, `draft:${row.draft_id}@${row.revision_count}`, chain.id]);
162	
163	      return { ok: true as const, threadId: t.rows[0]!.id, chainId: chain.id };
164	    });
165	  } catch (e) {
166	    if (e instanceof OpenRefused) return { ok: false, reason: e.reason, detail: e.detail };
167	    throw e;
