171	class OpenRefused extends Error {
172	  constructor(readonly reason: OpenEditorialRefusal, readonly detail?: string) { super(reason); }
173	}
174	
175	/* ══════════════════════════════════════════════════════════════════════════
176	   READ — what the surface renders
177	   ══════════════════════════════════════════════════════════════════════════ */
178	
179	/**
180	 * ⭐ One rendered turn. The adjunct is the RELATIONSHIP the binding records —
181	 * ⛔ never inferred from what the turn happens to say.
182	 */
183	export interface EditorialThreadTurn {
184	  readonly turnIndex: number;
185	  readonly speaker: 'author' | 'maia';
186	  readonly body: string;
187	  readonly at: string;
188	  readonly adjunct:
189	    | null
190	    | { readonly kind: 'direction'; readonly id: string; readonly instruction: string; readonly refersTo: string | null }
191	    | { readonly kind: 'version'; readonly id: string; readonly wording: string; readonly supersedes: string | null };
192	}
193	
194	/**
195	 * ⭐ One formulation in the authored succession.
196	 *
197	 * ⛔ THIS IS NOT A TURN, and the two are deliberately different structures:
198	 *
199	 *     turns      conversation order
200	 *     versions   authored succession
201	 *
202	 * ⛔ They are never merged into one timestamped feed. A version authored in the
203	 * composer has no turn at all, and a chronological merge would have to invent a
204	 * position for it among things that were said.
205	 */
206	export interface EditorialThreadVersion {
207	  readonly id: string;
208	  readonly author: VersionAuthor;
209	  readonly wording: string;
210	  readonly supersedes: string | null;
211	  readonly rationale: string | null;
