213	
214	export interface EditorialThreadView {
215	  readonly threadId: string;
216	  readonly chainId: string;
217	  /**
218	   * ⭐ WHICH WORK THIS EXCHANGE BELONGS TO, so a surface can hold a per-Work
219	   * setting (WS-EDITORIAL-SCOPE-01 · sequence override).
220	   *
221	   * ⛔⛔ EXPOSING IT ON A READ IS NOT THE SAME AS ACCEPTING IT ON A WRITE. The
222	   * turn route's closed body still refuses `workId` and always must: a value
223	   * the server DERIVES is not a value the browser may assert. This is the
224	   * member's own Work, named to the member, on a member-scoped read.
225	   */
226	  readonly workId: string;
227	  /** ⭐ The writer's own wording at the locus, as the chain froze it. */
228	  readonly locusText: string;
229	  /**
