237	   * the `ChangeLocator` law forbids.
238	   */
239	  readonly targetSectionId: string | null;
240	  readonly sectionLabel: string | null;
241	  /**
242	   * ⚠️ EDITORIAL-LEGACY-LOCUS-DISPOSITION-01 — this relationship's frozen locus
243	   * was written in the pre-alignment stored coordinate space and can never be
244	   * located in the projected one.
245	   *
246	   * ⭐ THE SURFACE NEEDS IT BEFORE SHE CHOOSES. Without it she would pick a
247	   * version, confirm an adoption, and only then meet a refusal — so the fact
248	   * that belongs to the relationship is reported with the relationship.
249	   *
250	   * ⛔ It withholds adoption and NOTHING ELSE. The exchange stays readable and
251	   * comparable; the chain is untouched; ⛔ nothing here says her Work moved.
252	   */
253	  readonly legacyLocus: boolean;
254	  readonly turns: readonly EditorialThreadTurn[];
255	  /**
256	   * ⭐⭐ THE COMPLETE STRUCTURAL LINEAGE, in succession order.
257	   *
258	   * ⚠️ UI-01 exposed versions ONLY through turn bindings, so a formulation
259	   * authored in a composer — which lawfully has no turn — would have been
260	   * DURABLE AND INVISIBLE. ⛔ The repair is not chronology: it is the chain's
261	   * own validated succession, read through `readProposalWork`, which already
262	   * owns read → validateChain → lineage. ⛔ No second ordering algorithm.
263	   */
