278	 * survives close, reopen and navigation: nothing below is reconstructed from a
279	 * component, and there is no client transcript to disagree with it.
280	 */
281	export async function readEditorialThread(
282	  identity: VerifiedIdentity, threadId: string,
283	): Promise<ReadEditorialResult> {
284	  const memberId = identity.memberId;
285	  /* ⭐ ADOPTION-01 · PHASE B — the target section and the writer's own name for
286	     it, DERIVED HERE, in the read that already proves thread ownership.
287	     ⛔ The browser must never name the place a change belongs; that is the
288	     `ChangeLocator` law one layer up, and it starts with the label. */
289	  const t = await query<{
290	    proposal_chain_id: string | null; expected_text: string | null;
291	    target_section_id: string | null; heading: string | null;
292	  }>(
293	    `SELECT th.proposal_chain_id, c.expected_text, c.target_section_id, ms.heading
294	       FROM ask_threads th
295	       LEFT JOIN proposal_chains c ON c.id = th.proposal_chain_id
296	       LEFT JOIN manuscript_draft_sections ds ON ds.id = c.target_section_id
297	       LEFT JOIN manuscript_sections ms ON ms.id = ds.source_section_id
298	      WHERE th.id = $1 AND th.member_id = $2`,
299	    [threadId, memberId]);
300	  if (t.rows.length === 0) return { ok: false, reason: 'thread_not_found' };
301	  const chainId = t.rows[0]!.proposal_chain_id;
302	  if (chainId === null) return { ok: false, reason: 'not_editorial' };
303	
304	  /* ⭐ ONE READ, LEFT-JOINED THROUGH THE BINDING. The adjunct arrives because a
305	     binding names it — ⛔ not because a turn's text resembles one. */
306	  const rows = await query<{
307	    turn_index: number; speaker: string; body: string; created_at: Date;
308	    direction_id: string | null; instruction: string | null; refers_to_version_id: string | null;
309	    version_id: string | null; formulation: string | null; supersedes: string | null;
310	  }>(
311	    `SELECT tu.turn_index, tu.speaker, tu.body, tu.created_at,
312	            b.direction_id, d.instruction, d.refers_to_version_id,
313	            b.version_id, v.formulation, v.supersedes
314	       FROM ask_turns tu
315	       LEFT JOIN editorial_turn_bindings b
316	              ON b.thread_id = tu.thread_id AND b.turn_index = tu.turn_index
317	       LEFT JOIN proposal_chain_directions d ON d.id = b.direction_id
318	       LEFT JOIN proposal_versions v ON v.id = b.version_id
319	      WHERE tu.thread_id = $1
320	      ORDER BY tu.turn_index`,
321	    [threadId]);
322	
323	  const turns: EditorialThreadTurn[] = rows.rows.map((r) => ({
324	    turnIndex: Number(r.turn_index),
325	    speaker: r.speaker === 'maia' ? 'maia' : 'author',
326	    body: r.body,
327	    at: new Date(r.created_at).toISOString(),
328	    adjunct: r.direction_id
329	      ? { kind: 'direction', id: r.direction_id, instruction: r.instruction ?? '', refersTo: r.refers_to_version_id }
330	      : r.version_id
331	        ? { kind: 'version', id: r.version_id, wording: r.formulation ?? '', supersedes: r.supersedes }
332	        : null,
333	  }));
334	
335	  /* ⭐ THE SUCCESSION, FROM THE READ THAT ALREADY VALIDATES IT. A corrupt chain
336	     REFUSES here exactly as it refuses there — ⛔ a view that quietly worked
337	     around broken succession would show the writer a history nobody authored. */
338	  const work = await readProposalWork(memberId, chainId);
339	  if (!work.ok) return { ok: false, reason: 'chain_unreadable' };
340	  const versions: EditorialThreadVersion[] = work.work.versions.map((v) => ({
341	    id: v.id,
342	    author: v.author,
343	    wording: v.replacementText,
344	    supersedes: v.supersedes,
345	    rationale: v.rationale ?? null,
346	  }));
347	
348	  return {
349	    ok: true,
350	    view: {
351	      application: await readApplicationRecovery(memberId, threadId),
352	      threadId, chainId,
353	      /* ⭐ From the same validated read as the succession. ⛔ Not a second lookup. */
354	      workId: work.work.chain.locus.workId,
355	      locusText: t.rows[0]!.expected_text ?? '',
356	      targetSectionId: t.rows[0]!.target_section_id,
357	      sectionLabel: t.rows[0]!.heading,
358	      /* ⭐ THE SAME PURE PREDICATE THE ADOPTION SEAM ASKS — one implementation,
359	         so the panel and the act can never disagree about which relationships
360	         are adoptable. */
361	      legacyLocus: !locusIsAdoptable(t.rows[0]!.expected_text ?? '', t.rows[0]!.heading),
362	      turns,
363	      versions,
364	      /* ⛔ Read off the LINEAGE, never off `versions[length-1]` of an unordered
365	         read — `readProposalWork` returns them in succession order. */
366	      headVersionId: versions.length ? versions[versions.length - 1]!.id : null,
367	    },
368	  };
369	}
